SUBROUTINE MTPRD (M, N, A, IA, JA, X, Y)
IMPLICIT NONE
INTEGER M, N
INTEGER I, J, L, LMAX, LMIN
!-----------------------------------------------------------------------
!              PRODUCT OF A VECTOR AND A SPARSE MATRIX
!-----------------------------------------------------------------------
REAL A(*), X(M), Y(N), T
INTEGER IA(*), JA(*)
!
DO J = 1,N
   Y(J) = 0.0
END DO
!
do 21 I = 1,M
   T = X(I)
   LMIN = IA(I)
   LMAX = IA(I+1) - 1
   IF (LMIN .GT. LMAX) GO TO 21
   DO L = LMIN,LMAX
      J = JA(L)
      Y(J) = Y(J) + T*A(L)
   END DO
21 CONTINUE
RETURN
END SUBROUTINE MTPRD

SUBROUTINE MTPRD1 (M, N, A, IA, JA, X, Y)
IMPLICIT NONE
INTEGER M, N
INTEGER I, J, L, LMAX, LMIN
!-----------------------------------------------------------------------
!     SET Y = X*A + Y WHERE A IS A SPARSE MATRIX AND X,Y ARE VECTORS
!-----------------------------------------------------------------------
REAL A(*), X(M), Y(N), T
INTEGER IA(*), JA(*)
!
do 11 I = 1,M
   T = X(I)
   LMIN = IA(I)
   LMAX = IA(I+1) - 1
   IF (LMIN .GT. LMAX) GO TO 11
   DO L = LMIN,LMAX
      J = JA(L)
      Y(J) = Y(J) + T*A(L)
   END DO
11 CONTINUE
RETURN
END SUBROUTINE MTPRD1

SUBROUTINE DVPRD (M, N, A, IA, JA, X, Y)
IMPLICIT NONE
INTEGER M, N
INTEGER I, J, L, LMAX, LMIN
!-----------------------------------------------------------------------
!              PRODUCT OF A SPARSE MATRIX AND A VECTOR
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), X(N), Y(M), SUM
INTEGER IA(*), JA(*)
!
do 11 I = 1,M
   SUM = 0.D0
   LMIN = IA(I)
   LMAX = IA(I+1) - 1
   IF (LMIN .GT. LMAX) GO TO 11
   DO L = LMIN,LMAX
      J = JA(L)
      SUM = SUM + A(L)*X(J)
   END DO
11 Y(I) = SUM
RETURN
END SUBROUTINE DVPRD

SUBROUTINE DVPRD1 (M, N, A, IA, JA, X, Y)
IMPLICIT NONE
INTEGER M, N
INTEGER I, J, L, LMAX, LMIN
!-----------------------------------------------------------------------
!     SET Y = A*X + Y WHERE A IS A SPARSE MATRIX AND X,Y ARE VECTORS
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), X(N), Y(M), SUM
INTEGER IA(*), JA(*)
!
do 11 I = 1,M
   SUM = Y(I)
   LMIN = IA(I)
   LMAX = IA(I+1) - 1
   IF (LMIN .GT. LMAX) GO TO 11
   DO L = LMIN,LMAX
      J = JA(L)
      SUM = SUM + A(L)*X(J)
   END DO
11 Y(I) = SUM
RETURN
END SUBROUTINE DVPRD1

