SUBROUTINE CVPRD (M, N, A, IA, JA, X, Y)
IMPLICIT NONE
INTEGER M, N
INTEGER I, J, L, LMAX, LMIN
!-----------------------------------------------------------------------
!              PRODUCT OF A SPARSE MATRIX AND A VECTOR
!-----------------------------------------------------------------------
COMPLEX A(*), X(N), Y(M), SUM
INTEGER IA(*), JA(*)
!
do 11 I = 1,M
   SUM = (0.0, 0.0)
   LMIN = IA(I)
   LMAX = IA(I+1) - 1
   IF (LMIN .GT. LMAX) GO TO 11
   DO L = LMIN,LMAX
      J = JA(L)
      SUM = SUM + A(L)*X(J)
   END DO
11 Y(I) = SUM
RETURN
END SUBROUTINE CVPRD

