!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 Z(I,MP) = A(I,MP-1)
!
   I = INT(MP)
   IF (I .EQ. MP) GO TO 140
!
   DO J = MP, IGH
      Z(MP,J) = Z(I,J)
      Z(I,J) = 0.0
   END DO
!
   Z(I,MP) = 1.0
140 CONTINUE
!
200 RETURN
END SUBROUTINE ELTRN0

SUBROUTINE ORTRAN(NM,N,LOW,IGH,A,ORT,Z)
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
REAL A(NM,IGH),ORT(IGH),Z(NM,N)
REAL G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL GENERAL
!     MATRIX TO UPPER HESSENBERG FORM BY  ORTHES.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES
!          IN ITS STRICT LOWER TRIANGLE,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ORTHES,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE ORTRAN

SUBROUTINE ORTRN1(N,LOW,IGH,A,NA,Z,NZ,ORT)
!
INTEGER I,J,N,KL,MM,MP,NA,IGH,LOW,MP1,NZ
REAL A(NA,IGH),ORT(IGH),Z(NZ,N)
REAL G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL GENERAL
!     MATRIX TO UPPER HESSENBERG FORM BY  ORTHES.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES
!          IN ITS STRICT LOWER TRIANGLE,
!
!        NA MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  A  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        NZ MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  Z  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  ORTHES.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  ORTHES,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.0
!
   Z(I,I) = 1.0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE ORTRN1

SUBROUTINE HQR2(NM,N,LOW,IGH,H,WR,WI,Z,IERR)
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,MM,NA,NM,NN, &
&IGH,ITS,LOW,MP2,ENM2,IERR
REAL H(NM,N),WR(N),WI(N),Z(NM,N)
REAL P,Q,R,S,T,W,X,Y,RA,SA,VI,VR,ZZ,NORM,MACHEP,SPMPAR
!     REAL SQRT,ABS
!     INTEGER MIN0
LOGICAL NOTLAS
COMPLEX Z3
!     COMPLEX CMPLX
!     REAL REAL,AIMAG
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR2,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A REAL UPPER HESSENBERG MATRIX BY THE QR METHOD.  THE
!     EIGENVECTORS OF A REAL GENERAL MATRIX CAN ALSO BE FOUND
!     IF  ELMHES  AND  ELTRAN  OR  ORTHES  AND  ORTRAN  HAVE
!     BEEN USED TO REDUCE THIS GENERAL MATRIX TO HESSENBERG FORM
!     AND TO ACCUMULATE THE SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  BALANC.  IF  BALANC  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED BY  ELTRAN
!          AFTER THE REDUCTION BY  ELMHES, OR BY  ORTRAN  AFTER THE
!          REDUCTION BY  ORTHES, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE HESSENBERG MATRIX ARE DESIRED, Z MUST CONTAIN THE
!          IDENTITY MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGENVECTORS.
!          IF THE I-TH EIGENVALUE IS REAL, THE I-TH COLUMN OF Z
!          CONTAINS ITS EIGENVECTOR.  IF THE I-TH EIGENVALUE IS COMPLEX
!          WITH POSITIVE IMAGINARY PART, THE I-TH AND (I+1)-TH
!          COLUMNS OF Z CONTAIN THE REAL AND IMAGINARY PARTS OF ITS
!          EIGENVECTOR.  THE EIGENVECTORS ARE UNNORMALIZED.  IF AN
!          ERROR EXIT IS MADE, NONE OF THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!     ARITHMETIC IS REAL EXCEPT FOR THE REPLACEMENT OF THE ALGOL
!     PROCEDURE CDIV BY COMPLEX DIVISION.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.0
K = 1
!     ********** STORE ROOTS ISOLATED BY BALANC
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + ABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.0
50 CONTINUE
!
EN = IGH
T = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 340
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = ABS(H(L-1,L-1)) + ABS(H(L,L))
   IF (S .EQ. 0.0) S = NORM
   IF (ABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 30) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = ABS(H(EN,NA)) + ABS(H(NA,ENM2))
X = 0.75 * S
Y = X
W = -0.4375 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = ABS(P) + ABS(Q) + ABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (ABS(H(M,M-1)) * (ABS(Q) + ABS(R)) .LE. MACHEP * ABS(P) &
&* (ABS(H(M-1,M-1)) + ABS(ZZ) + ABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.0
   IF (NOTLAS) R = H(K+2,K-1)
   X = ABS(P) + ABS(Q) + ABS(R)
   IF (X .EQ. 0.0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = SQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, N
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = 1, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
   DO I = LOW, IGH
      P = X * Z(I,K) + Y * Z(I,K+1)
      IF (.NOT. NOTLAS) GO TO 240
      P = P + ZZ * Z(I,K+2)
      Z(I,K+2) = Z(I,K+2) - P * R
240 Z(I,K+1) = Z(I,K+1) - P * Q
      Z(I,K) = Z(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 H(EN,EN) = X + T
WR(EN) = H(EN,EN)
WI(EN) = 0.0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.0
Q = P * P + W
ZZ = SQRT(ABS(Q))
H(EN,EN) = X + T
X = H(EN,EN)
H(NA,NA) = Y + T
IF (Q .LT. 0.0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.0) WR(EN) = X - W / ZZ
WI(NA) = 0.0
WI(EN) = 0.0
X = H(EN,NA)
S = ABS(X) + ABS(ZZ)
P = X / S
Q = ZZ / S
R = SQRT(P*P+Q*Q)
P = P / R
Q = Q / R
!     ********** ROW MODIFICATION **********
DO J = NA, N
   ZZ = H(NA,J)
   H(NA,J) = Q * ZZ + P * H(EN,J)
   H(EN,J) = Q * H(EN,J) - P * ZZ
END DO
!     ********** COLUMN MODIFICATION **********
DO I = 1, EN
   ZZ = H(I,NA)
   H(I,NA) = Q * ZZ + P * H(I,EN)
   H(I,EN) = Q * H(I,EN) - P * ZZ
END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
DO I = LOW, IGH
   ZZ = Z(I,NA)
   Z(I,NA) = Q * ZZ + P * Z(I,EN)
   Z(I,EN) = Q * Z(I,EN) - P * ZZ
END DO
!
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 IF (NORM .EQ. 0.0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 1 DO -- **********
do 800 NN = 1, N
   EN = N + 1 - NN
   P = WR(EN)
   Q = WI(EN)
   NA = EN - 1
   IF (Q) 710, 600, 800
!     ********** REAL VECTOR **********
600 M = EN
   H(EN,EN) = 1.0
   IF (NA .EQ. 0) GO TO 800
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   do 700 II = 1, NA
      I = EN - II
      W = H(I,I) - P
      R = H(I,EN)
      IF (M .GT. NA) GO TO 620
!
      do 610 J = M, NA
610 R = R + H(I,J) * H(J,EN)
!
620 IF (WI(I) .GE. 0.0) GO TO 630
      ZZ = W
      S = R
      GO TO 700
630 M = I
      IF (WI(I) .NE. 0.0) GO TO 640
      T = W
      IF (W .EQ. 0.0) T = MACHEP * NORM
      H(I,EN) = -R / T
      GO TO 700
!     ********** SOLVE REAL EQUATIONS **********
640 X = H(I,I+1)
      Y = H(I+1,I)
      Q = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I)
      T = (X * S - ZZ * R) / Q
      H(I,EN) = T
      IF (ABS(X) .LE. ABS(ZZ)) GO TO 650
      H(I+1,EN) = (-R - W * T) / X
      GO TO 700
650 H(I+1,EN) = (-S - Y * T) / ZZ
700 CONTINUE
!     ********** END REAL VECTOR **********
   GO TO 800
!     ********** COMPLEX VECTOR **********
710 M = NA
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   IF (ABS(H(EN,NA)) .LE. ABS(H(NA,EN))) GO TO 720
   H(NA,NA) = Q / H(EN,NA)
   H(NA,EN) = -(H(EN,EN) - P) / H(EN,NA)
   GO TO 730
720 Z3 = CMPLX(0.0,-H(NA,EN)) / CMPLX(H(NA,NA)-P,Q)
   H(NA,NA) = REAL(Z3)
   H(NA,EN) = AIMAG(Z3)
730 H(EN,NA) = 0.0
   H(EN,EN) = 1.0
   ENM2 = NA - 1
   IF (ENM2 .EQ. 0) GO TO 800
!     ********** FOR I=EN-2 STEP -1 UNTIL 1 DO -- **********
   do 790 II = 1, ENM2
      I = NA - II
      W = H(I,I) - P
      RA = 0.0
      SA = H(I,EN)
!
      DO J = M, NA
         RA = RA + H(I,J) * H(J,NA)
         SA = SA + H(I,J) * H(J,EN)
      END DO
!
      IF (WI(I) .GE. 0.0) GO TO 770
      ZZ = W
      R = RA
      S = SA
      GO TO 790
770 M = I
      IF (WI(I) .NE. 0.0) GO TO 780
      Z3 = CMPLX(-RA,-SA) / CMPLX(W,Q)
      H(I,NA) = REAL(Z3)
      H(I,EN) = AIMAG(Z3)
      GO TO 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 X = H(I,I+1)
      Y = H(I+1,I)
      VR = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I) - Q * Q
      VI = (WR(I) - P) * 2.0 * Q
      IF (VR .EQ. 0.0 .AND. VI .EQ. 0.0) VR = MACHEP * NORM &
&* (ABS(W) + ABS(Q) + ABS(X) + ABS(Y) + ABS(ZZ))
      Z3 = CMPLX(X*R-ZZ*RA+Q*SA,X*S-ZZ*SA-Q*RA) / CMPLX(VR,VI)
      H(I,NA) = REAL(Z3)
      H(I,EN) = AIMAG(Z3)
      IF (ABS(X) .LE. ABS(ZZ) + ABS(Q)) GO TO 785
      H(I+1,NA) = (-RA - W * H(I,NA) + Q * H(I,EN)) / X
      H(I+1,EN) = (-SA - W * H(I,EN) - Q * H(I,NA)) / X
      GO TO 790
785 Z3 = CMPLX(-R-Y*H(I,NA),-S-Y*H(I,EN)) / CMPLX(ZZ,Q)
      H(I+1,NA) = REAL(Z3)
      H(I+1,EN) = AIMAG(Z3)
790 CONTINUE
!     ********** END COMPLEX VECTOR **********
800 CONTINUE
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
!
   do 820 J = I, N
820 Z(I,J) = H(I,J)
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW DO -- **********
do 880 JJ = LOW, N
   J = N + LOW - JJ
   M = MIN0(J,IGH)
!
   do 880 I = LOW, IGH
      ZZ = 0.0
!
      do 860 K = LOW, M
860 ZZ = ZZ + Z(I,K) * H(K,J)
!
      Z(I,J) = ZZ
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE HQR2

SUBROUTINE DEIG (IBAL,A,KA,N,WR,WI,IERR)
!-----------------------------------------------------------------------
!                EIGENVALUES OF DOUBLE PRECISION MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DBAL (KA,N,A,LOW,IGH,WR)
CALL DORTH (KA,N,LOW,IGH,A,WR)
CALL DHQR (KA,N,LOW,IGH,A,WR,WI,IERR)
RETURN
END SUBROUTINE DEIG

SUBROUTINE DEIGV (IBAL,A,KA,N,WR,WI,ZR,ZI,IERR)
!-----------------------------------------------------------------------
!     EIGENVALUES AND EIGENVECTORS OF DOUBLE PRECISION MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(KA,N),WR(N),WI(N),ZR(KA,N),ZI(KA,N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DBAL (KA,N,A,LOW,IGH,ZI)
CALL DORTH (KA,N,LOW,IGH,A,WR)
CALL DORTRN (KA,N,LOW,IGH,A,WR,ZR)
CALL DHQR2 (KA,N,LOW,IGH,A,WR,WI,ZR,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL DBABK (KA,N,LOW,IGH,ZI,N,ZR)
!
do 30 K = 1,N
   IF (WI(K)) 30,10,20
10 do 11 J = 1,N
11 ZI(J,K) = 0.D0
   GO TO 30
20 KP1 = K + 1
   do 21 J = 1,N
      ZI(J,K) = ZR(J,KP1)
      ZR(J,KP1) = ZR(J,K)
21 ZI(J,KP1) = -ZI(J,K)
30 CONTINUE
RETURN
END SUBROUTINE DEIGV

SUBROUTINE DBAL(NM,N,A,LOW,IGH,SCALE)
!
INTEGER I,J,K,L,M,N,JJ,NM,IGH,LOW,IEXC
DOUBLE PRECISION A(NM,N),SCALE(N)
DOUBLE PRECISION C,F,G,R,S,B2,RADIX
INTEGER IPMPAR
!     DOUBLE PRECISION DABS
LOGICAL NOCONV
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALANCE,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     DBAL BALANCES A DOUBLE PRECISION REAL MATRIX AND ISOLATES
!     EIGENVALUES WHENEVER POSSIBLE.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE INPUT MATRIX TO BE BALANCED.
!
!     ON OUTPUT-
!
!        A CONTAINS THE BALANCED MATRIX,
!
!        LOW AND IGH ARE TWO INTEGERS SUCH THAT A(I,J)
!          IS EQUAL TO ZERO IF
!           (1) I IS GREATER THAN J AND
!           (2) J=1,...,LOW-1 OR I=IGH+1,...,N,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE
!           PERMUTATIONS AND SCALING FACTORS USED.
!
!     SUPPOSE THAT THE PRINCIPAL SUBMATRIX IN ROWS LOW THROUGH IGH
!     HAS BEEN BALANCED, THAT P(J) DENOTES THE INDEX INTERCHANGED
!     WITH J DURING THE PERMUTATION STEP, AND THAT THE ELEMENTS
!     OF THE DIAGONAL MATRIX USED ARE DENOTED BY D(I,J).  THEN
!        SCALE(J) = P(J),    FOR J = 1,...,LOW-1
!                 = D(J,J),      J = LOW,...,IGH
!                 = P(J)         J = IGH+1,...,N.
!     THE ORDER IN WHICH THE INTERCHANGES ARE MADE IS N TO IGH+1,
!     THEN 1 TO LOW-1.
!
!     NOTE THAT 1 IS RETURNED FOR IGH IF IGH IS ZERO FORMALLY.
!
!     THE ALGOL PROCEDURE EXC CONTAINED IN BALANCE APPEARS IN
!     DBAL IN LINE.  (NOTE THAT THE ALGOL ROLES OF IDENTIFIERS
!     K,L HAVE BEEN REVERSED.)
!
!-----------------------------------------------------------------------
!
!     ********** RADIX IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE BASE OF THE MACHINE FLOATING POINT REPRESENTATION.
!
           RADIX = IPMPAR(4)
!
!                **********
!
B2 = RADIX * RADIX
K = 1
L = N
GO TO 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 SCALE(M) = J
IF (J .EQ. M) GO TO 50
!
DO I = 1, L
   F = A(I,J)
   A(I,J) = A(I,M)
   A(I,M) = F
END DO
!
DO I = K, N
   F = A(J,I)
   A(J,I) = A(M,I)
   A(M,I) = F
END DO
!
50 GO TO (80,130), IEXC
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 IF (L .EQ. 1) GO TO 280
L = L - 1
!     ********** FOR J=L STEP -1 UNTIL 1 DO -- **********
100 do 120 JJ = 1, L
   J = L + 1 - JJ
!
   do 110 I = 1, L
      IF (I .EQ. J) GO TO 110
      IF (A(J,I) .NE. 0.D0) GO TO 120
110 CONTINUE
!
   M = L
   IEXC = 1
   GO TO 20
120 CONTINUE
!
GO TO 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 K = K + 1
!
140 do 170 J = K, L
!
   do 150 I = K, L
      IF (I .EQ. J) GO TO 150
      IF (A(I,J) .NE. 0.D0) GO TO 170
150 CONTINUE
!
   M = K
   IEXC = 2
   GO TO 20
170 CONTINUE
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS K TO L **********
do 180 I = K, L
180 SCALE(I) = 1.D0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 NOCONV = .FALSE.
!
do 270 I = K, L
   C = 0.D0
   R = 0.D0
!
   do 200 J = K, L
      IF (J .EQ. I) GO TO 200
      C = C + DABS(A(J,I))
      R = R + DABS(A(I,J))
200 CONTINUE
!     ********** GUARD AGAINST ZERO C OR R DUE TO UNDERFLOW **********
   IF (C .EQ. 0.D0 .OR. R .EQ. 0.D0) GO TO 270
   G = R / RADIX
   F = 1.D0
   S = C + R
210 IF (C .GE. G) GO TO 220
   F = F * RADIX
   C = C * B2
   GO TO 210
220 G = R * RADIX
230 IF (C .LT. G) GO TO 240
   F = F / RADIX
   C = C / B2
   GO TO 230
!     ********** NOW BALANCE **********
240 IF ((C + R) / F .GE. 0.95D0 * S) GO TO 270
   G = 1.D0 / F
   SCALE(I) = SCALE(I) * F
   NOCONV = .TRUE.
!
   do 250 J = K, N
250 A(I,J) = A(I,J) * G
!
   do 260 J = 1, L
260 A(J,I) = A(J,I) * F
!
270 CONTINUE
!
IF (NOCONV) GO TO 190
!
280 LOW = K
IGH = L
RETURN
END SUBROUTINE DBAL

SUBROUTINE DBALNV (NZ,N,Z,LOW,IGH,SCALE)
INTEGER I,J,K,N,II,NZ,IGH,LOW
DOUBLE PRECISION Z(NZ,N),SCALE(N)
DOUBLE PRECISION S
!-----------------------------------------------------------------------
!        GIVEN A MATRIX A OF ORDER N. DBAL TRANSFORMS A INTO
!     THE MATRIX B BY THE SIMILARITY TRANSFORMATION
!             B = D**(-1)*TRANSPOSE(P)*A*P*D
!     WHERE D IS A DIAGONAL MATRIX AND P A PERMUTATION MATRIX.
!     THE INFORMATION CONCERNING D AND P IS STORED IN IGH, LOW,
!     AND SCALE. THE ORDER IN WHICH THE INTERCHANGES WERE MADE
!     IS N TO IGH + 1, AND THEN 1 TO LOW - 1.
!
!        Z IS A MATRIX OF ORDER N. DBALNV TRANSFORMS Z INTO THE
!     MATRIX W USING THE INVERSE SIMILARITY TRANSFORM
!             W = P*D*Z*D**(-1)*TRANSPOSE(P)
!
!     ON INPUT-
!
!        NZ IS THE ROW DIMENSION OF THE MATRIX Z IN THE CALLING
!          PROGRAM,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY  DBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY  DBAL,
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMED MATRIX W
!
!-----------------------------------------------------------------------
!
IF (IGH .EQ. LOW) GO TO 30
!
DO I = LOW, IGH
S = SCALE(I)
   do 10 J = 1, N
10 Z(I,J) = Z(I,J) * S
END DO
!
DO J = LOW, IGH
S = 1.D0/SCALE(J)
   do 20 I = 1, N
20 Z(I,J) = Z(I,J) * S
END DO
!
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
!
30 do 60 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 60
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 60
!
   do 40 J = 1, N
      S = Z(I,J)
      Z(I,J) = Z(K,J)
40 Z(K,J) = S
!
   do 50 J = 1, N
      S = Z(J,I)
      Z(J,I) = Z(J,K)
50 Z(J,K) = S
60 CONTINUE
RETURN
END SUBROUTINE DBALNV

SUBROUTINE DORTH(NM,N,LOW,IGH,A,ORT)
!
INTEGER I,J,M,N,II,JJ,LA,MP,NM,IGH,KP1,LOW
DOUBLE PRECISION A(NM,N),ORT(IGH)
DOUBLE PRECISION F,G,H,SCALE
!     DOUBLE PRECISION DSQRT,DABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTHES,
!     NUM. MATH. 12, 349-368(1968) BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A REAL GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS THE INPUT MATRIX.
!
!     ON OUTPUT-
!
!        A CONTAINS THE HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE ORTHOGONAL TRANSFORMATIONS USED IN THE REDUCTION
!          IS STORED IN THE REMAINING TRIANGLE UNDER THE
!          HESSENBERG MATRIX,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANSFORMATIONS.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
!
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   H = 0.D0
   ORT(M) = 0.D0
   SCALE = 0.D0
!     ********** SCALE COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 I = M, IGH
90 SCALE = SCALE + DABS(A(I,M-1))
!
   IF (SCALE .EQ. 0.D0) GO TO 180
   MP = M + IGH
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
   DO II = M, IGH
      I = MP - II
      ORT(I) = A(I,M-1) / SCALE
      H = H + ORT(I) * ORT(I)
   END DO
!
   G = DSQRT(H)
   IF (ORT(M) .GE. 0.D0) G = -G
   H = H - ORT(M) * G
   ORT(M) = ORT(M) - G
!     ********** FORM (I-(U*UT)/H) * A **********
   DO J = M, N
      F = 0.D0
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
      DO II = M, IGH
         I = MP - II
         F = F + ORT(I) * A(I,J)
      END DO
!
      F = F / H
!
      do 120 I = M, IGH
120 A(I,J) = A(I,J) - F * ORT(I)
!
   END DO
!     ********** FORM (I-(U*UT)/H)*A*(I-(U*UT)/H) **********
   DO I = 1, IGH
      F = 0.D0
!     ********** FOR J=IGH STEP -1 UNTIL M DO -- **********
      DO JJ = M, IGH
         J = MP - JJ
         F = F + ORT(J) * A(I,J)
      END DO
!
      F = F / H
!
      do 150 J = M, IGH
150 A(I,J) = A(I,J) - F * ORT(J)
!
   END DO
!
   ORT(M) = SCALE * ORT(M)
   A(M,M-1) = SCALE * G
180 CONTINUE
!
200 RETURN
END SUBROUTINE DORTH

SUBROUTINE DHQR(NM,N,LOW,IGH,H,WR,WI,IERR)
!
INTEGER I,J,K,L,M,N,EN,LL,MM,NA,NM,IGH,ITS,LOW,MP2,ENM2,IERR
DOUBLE PRECISION H(NM,N),WR(N),WI(N)
DOUBLE PRECISION P,Q,R,S,T,W,X,Y,ZZ,NORM,MACHEP,DPMPAR
!     DOUBLE PRECISION DSQRT,DABS
!     INTEGER MIN0
LOGICAL NOTLAS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR,
!     NUM. MATH. 14, 219-231(1970) BY MARTIN, PETERS, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 359-371(1971).
!
!     DHQR FINDS THE EIGENVALUES OF A DOUBLE PRECISION REAL
!     UPPER HESSENBERG MATRIX BY THE QR METHOD.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX.  INFORMATION ABOUT
!          THE TRANSFORMATIONS USED IN THE REDUCTION TO HESSENBERG
!          FORM BY DORTH, IF PERFORMED, IS STORED
!          IN THE REMAINING TRIANGLE UNDER THE HESSENBERG MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED.  THEREFORE, IT MUST BE SAVED
!          BEFORE CALLING  HQR  IF SUBSEQUENT CALCULATION AND
!          BACK TRANSFORMATION OF EIGENVECTORS IS TO BE PERFORMED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0
!                IN THE DOUBLE PRECISION ARITHMETIC BEING USED.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.D0
K = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + DABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.D0
50 CONTINUE
!
EN = IGH
T = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 1001
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = DABS(H(L-1,L-1)) + DABS(H(L,L))
   IF (S .EQ. 0.D0) S = NORM
   IF (DABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20 .AND. ITS .NE. 30) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = DABS(H(EN,NA)) + DABS(H(NA,ENM2))
X = .75D0 * S
Y = X
W = -.4375D0 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = DABS(P) + DABS(Q) + DABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (DABS(H(M,M-1)) * (DABS(Q) + DABS(R)) .LE. MACHEP * DABS(P) &
&* (DABS(H(M-1,M-1)) + DABS(ZZ) + DABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.D0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.D0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.D0
   IF (NOTLAS) R = H(K+2,K-1)
   X = DABS(P) + DABS(Q) + DABS(R)
   IF (X .EQ. 0.D0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = DSQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.D0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, EN
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = L, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 WR(EN) = X + T
WI(EN) = 0.D0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.D0
Q = P * P + W
ZZ = DSQRT(DABS(Q))
X = X + T
IF (Q .LT. 0.D0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.D0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.D0) WR(EN) = X - W / ZZ
WI(NA) = 0.D0
WI(EN) = 0.D0
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE DHQR

SUBROUTINE DBABK(NM,N,LOW,IGH,SCALE,M,Z)
!
INTEGER I,J,K,M,N,II,NM,IGH,LOW
DOUBLE PRECISION SCALE(N),Z(NM,M)
DOUBLE PRECISION S
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE BALBAK,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE FORMS THE EIGENVECTORS OF A REAL GENERAL
!     MATRIX BY BACK TRANSFORMING THOSE OF THE CORRESPONDING
!     BALANCED MATRIX DETERMINED BY DBAL.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY DBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY DBAL,
!
!        M IS THE NUMBER OF COLUMNS OF Z TO BE BACK TRANSFORMED,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGEN-
!          VECTORS TO BE BACK TRANSFORMED IN ITS FIRST M COLUMNS.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE
!          TRANSFORMED EIGENVECTORS IN ITS FIRST M COLUMNS.
!
!-----------------------------------------------------------------------
!
IF (M .EQ. 0) GO TO 200
IF (IGH .EQ. LOW) GO TO 120
!
DO I = LOW, IGH
   S = SCALE(I)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                IF THE FOREGOING STATEMENT IS REPLACED BY
!                S=1.0/SCALE(I). **********
   do 100 J = 1, M
100 Z(I,J) = Z(I,J) * S
!
END DO
!     ********- FOR I=LOW-1 STEP -1 UNTIL 1,
!               IGH+1 STEP 1 UNTIL N DO -- **********
120 do 140 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 140
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 140
!
   DO J = 1, M
      S = Z(I,J)
      Z(I,J) = Z(K,J)
      Z(K,J) = S
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DBABK

SUBROUTINE DORTRN(NM,N,LOW,IGH,A,ORT,Z)
!
INTEGER I,J,N,KL,MM,MP,NM,IGH,LOW,MP1
DOUBLE PRECISION A(NM,IGH),ORT(IGH),Z(NM,N)
DOUBLE PRECISION G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL DOUBLE
!     PRECISION MATRIX TO UPPER HESSENBERG FORM BY DORTH.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH
!          IN ITS STRICT LOWER TRIANGLE,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY DORTH,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.D0
!
   Z(I,I) = 1.D0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.D0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.D0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DORTRN

SUBROUTINE DRTRN1(N,LOW,IGH,A,NA,Z,NZ,ORT)
!
INTEGER I,J,N,KL,MM,MP,NA,IGH,LOW,MP1,NZ
DOUBLE PRECISION A(NA,IGH),ORT(IGH),Z(NZ,N)
DOUBLE PRECISION G
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE ORTRANS,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE ACCUMULATES THE ORTHOGONAL SIMILARITY
!     TRANSFORMATIONS USED IN THE REDUCTION OF A REAL DOUBLE
!     PRECISION MATRIX TO UPPER HESSENBERG FORM BY DORTH.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH
!          IN ITS STRICT LOWER TRIANGLE,
!
!        NA MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  A  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        NZ MUST BE SET TO THE ROW DIMENSION OF THE 2-DIMENSIONAL
!          ARRAY PARAMETER  Z  AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        ORT CONTAINS FURTHER INFORMATION ABOUT THE TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DORTH.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!     ON OUTPUT-
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY DORTH,
!
!        ORT HAS BEEN ALTERED.
!
!-----------------------------------------------------------------------
!
!     ********** INITIALIZE Z TO IDENTITY MATRIX **********
DO I = 1, N
!
   do 60 J = 1, N
60 Z(I,J) = 0.D0
!
   Z(I,I) = 1.D0
END DO
!
KL = IGH - LOW - 1
IF (KL .LT. 1) GO TO 200
!     ********** FOR MP=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
do 140 MM = 1, KL
   MP = IGH - MM
   IF (A(MP,MP-1) .EQ. 0.D0) GO TO 140
   MP1 = MP + 1
!
   do 100 I = MP1, IGH
100 ORT(I) = A(I,MP-1)
!
   DO J = MP, IGH
      G = 0.D0
!
      do 110 I = MP, IGH
110 G = G + ORT(I) * Z(I,J)
!     ********** DIVISOR BELOW IS NEGATIVE OF H FORMED IN ORTHES.
!                DOUBLE DIVISION AVOIDS POSSIBLE UNDERFLOW **********
      G = (G / ORT(MP)) / A(MP,MP-1)
!
      do 120 I = MP, IGH
120 Z(I,J) = Z(I,J) + G * ORT(I)
!
   END DO
!
140 CONTINUE
!
200 RETURN
END SUBROUTINE DRTRN1

SUBROUTINE DHQR2(NM,N,LOW,IGH,H,WR,WI,Z,IERR)
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,MM,NA,NM,NN, &
&IGH,ITS,LOW,MP2,ENM2,IERR
DOUBLE PRECISION H(NM,N),WR(N),WI(N),Z(NM,N)
DOUBLE PRECISION A,B,D,P,Q,R,S,T,U,W,X,Y
DOUBLE PRECISION RA,SA,VI,VR,ZZ,NORM,MACHEP
!     INTEGER MIN0
!     DOUBLE PRECISION DSQRT,DABS
DOUBLE PRECISION DPMPAR
LOGICAL NOTLAS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE HQR2,
!     NUM. MATH. 16, 181-204(1970) BY PETERS AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A REAL DOUBLE PRECISION UPPER HESSENBERG MATRIX BY THE
!     QR METHOD.  THE EIGENVECTORS OF A REAL GENERAL MATRIX CAN
!     ALSO BE FOUND IF DORTH AND DORTRN HAVE BEEN USED TO REDUCE
!     THIS GENERAL MATRIX TO HESSENBERG FORM AND TO ACCUMULATE
!     THE SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DBAL.  IF DBAL HAS NOT BEEN USED THEN
!          SET LOW=1, IGH=N,
!
!        H CONTAINS THE UPPER HESSENBERG MATRIX,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED BY DORTRN
!          AFTER THE REDUCTION BY DORTH, IF PERFORMED. IF THE
!          EIGENVECTORS OF THE HESSENBERG MATRIX ARE DESIRED,
!          Z MUST CONTAIN THE IDENTITY MATRIX.
!
!     ON OUTPUT-
!
!        H HAS BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  THE EIGENVALUES
!          ARE UNORDERED EXCEPT THAT COMPLEX CONJUGATE PAIRS
!          OF VALUES APPEAR CONSECUTIVELY WITH THE EIGENVALUE
!          HAVING THE POSITIVE IMAGINARY PART FIRST.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        Z CONTAINS THE REAL AND IMAGINARY PARTS OF THE EIGENVECTORS.
!          IF THE I-TH EIGENVALUE IS REAL, THE I-TH COLUMN OF Z
!          CONTAINS ITS EIGENVECTOR.  IF THE I-TH EIGENVALUE IS COMPLEX
!          WITH POSITIVE IMAGINARY PART, THE I-TH AND (I+1)-TH
!          COLUMNS OF Z CONTAIN THE REAL AND IMAGINARY PARTS OF ITS
!          EIGENVECTOR.  THE EIGENVECTORS ARE UNNORMALIZED.  IF AN
!          ERROR EXIT IS MADE, NONE OF THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0
!                IN THE DOUBLE PRECISION ARITHMETIC BEING USED.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
NORM = 0.D0
K = 1
!     ********** STORE ROOTS ISOLATED BY DBAL
!                AND COMPUTE MATRIX NORM **********
do 50 I = 1, N
!
   do 40 J = K, N
40 NORM = NORM + DABS(H(I,J))
!
   K = I
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 50
   WR(I) = H(I,I)
   WI(I) = 0.D0
50 CONTINUE
!
EN = IGH
T = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUES **********
60 IF (EN .LT. LOW) GO TO 340
ITS = 0
NA = EN - 1
ENM2 = NA - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
70 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 100
   S = DABS(H(L-1,L-1)) + DABS(H(L,L))
   IF (S .EQ. 0.D0) S = NORM
   IF (DABS(H(L,L-1)) .LE. MACHEP * S) GO TO 100
END DO
!     ********** FORM SHIFT **********
100 X = H(EN,EN)
IF (L .EQ. EN) GO TO 270
Y = H(NA,NA)
W = H(EN,NA) * H(NA,EN)
IF (L .EQ. NA) GO TO 280
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .NE. 10 .AND. ITS .NE. 20 .AND. ITS .NE. 30) GO TO 130
!     ********** FORM EXCEPTIONAL SHIFT **********
T = T + X
!
do 120 I = LOW, EN
120 H(I,I) = H(I,I) - X
!
S = DABS(H(EN,NA)) + DABS(H(NA,ENM2))
X = .75D0 * S
Y = X
W = -.4375D0 * S * S
130 ITS = ITS + 1
!     ********** LOOK FOR TWO CONSECUTIVE SMALL
!                SUB-DIAGONAL ELEMENTS.
!                FOR M=EN-2 STEP -1 UNTIL L DO -- **********
DO MM = L, ENM2
   M = ENM2 + L - MM
   ZZ = H(M,M)
   R = X - ZZ
   S = Y - ZZ
   P = (R * S - W) / H(M+1,M) + H(M,M+1)
   Q = H(M+1,M+1) - ZZ - R - S
   R = H(M+2,M+1)
   S = DABS(P) + DABS(Q) + DABS(R)
   P = P / S
   Q = Q / S
   R = R / S
   IF (M .EQ. L) GO TO 150
   IF (DABS(H(M,M-1)) * (DABS(Q) + DABS(R)) .LE. MACHEP * DABS(P) &
&* (DABS(H(M-1,M-1)) + DABS(ZZ) + DABS(H(M+1,M+1)))) GO TO 150
END DO
!
150 MP2 = M + 2
!
do 160 I = MP2, EN
   H(I,I-2) = 0.D0
   IF (I .EQ. MP2) GO TO 160
   H(I,I-3) = 0.D0
160 CONTINUE
!     ********** DOUBLE QR STEP INVOLVING ROWS L TO EN AND
!                COLUMNS M TO EN **********
do 260 K = M, NA
   NOTLAS = K .NE. NA
   IF (K .EQ. M) GO TO 170
   P = H(K,K-1)
   Q = H(K+1,K-1)
   R = 0.D0
   IF (NOTLAS) R = H(K+2,K-1)
   X = DABS(P) + DABS(Q) + DABS(R)
   IF (X .EQ. 0.D0) GO TO 260
   P = P / X
   Q = Q / X
   R = R / X
170 S = DSQRT(P*P + Q*Q + R*R)
   IF (P .LT. 0.D0) S = -S
   IF (K .EQ. M) GO TO 180
   H(K,K-1) = -S * X
   GO TO 190
180 IF (L .NE. M) H(K,K-1) = -H(K,K-1)
190 P = P + S
   X = P / S
   Y = Q / S
   ZZ = R / S
   Q = Q / P
   R = R / P
!     ********** ROW MODIFICATION **********
   DO J = K, N
      P = H(K,J) + Q * H(K+1,J)
      IF (.NOT. NOTLAS) GO TO 200
      P = P + R * H(K+2,J)
      H(K+2,J) = H(K+2,J) - P * ZZ
200 H(K+1,J) = H(K+1,J) - P * Y
      H(K,J) = H(K,J) - P * X
   END DO
!
   J = MIN0(EN,K+3)
!     ********** COLUMN MODIFICATION **********
   DO I = 1, J
      P = X * H(I,K) + Y * H(I,K+1)
      IF (.NOT. NOTLAS) GO TO 220
      P = P + ZZ * H(I,K+2)
      H(I,K+2) = H(I,K+2) - P * R
220 H(I,K+1) = H(I,K+1) - P * Q
      H(I,K) = H(I,K) - P
   END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
   DO I = LOW, IGH
      P = X * Z(I,K) + Y * Z(I,K+1)
      IF (.NOT. NOTLAS) GO TO 240
      P = P + ZZ * Z(I,K+2)
      Z(I,K+2) = Z(I,K+2) - P * R
240 Z(I,K+1) = Z(I,K+1) - P * Q
      Z(I,K) = Z(I,K) - P
   END DO
!
260 CONTINUE
!
GO TO 70
!     ********** ONE ROOT FOUND **********
270 H(EN,EN) = X + T
WR(EN) = H(EN,EN)
WI(EN) = 0.D0
EN = NA
GO TO 60
!     ********** TWO ROOTS FOUND **********
280 P = (Y - X) / 2.D0
Q = P * P + W
ZZ = DSQRT(DABS(Q))
H(EN,EN) = X + T
X = H(EN,EN)
H(NA,NA) = Y + T
IF (Q .LT. 0.D0) GO TO 320
!     ********** REAL PAIR **********
IF (P .LT. 0.D0) ZZ = -ZZ
ZZ = P + ZZ
WR(NA) = X + ZZ
WR(EN) = WR(NA)
IF (ZZ .NE. 0.D0) WR(EN) = X - W / ZZ
WI(NA) = 0.D0
WI(EN) = 0.D0
X = H(EN,NA)
S = DABS(X) + DABS(ZZ)
P = X / S
Q = ZZ / S
R = DSQRT(P*P+Q*Q)
P = P / R
Q = Q / R
!     ********** ROW MODIFICATION **********
DO J = NA, N
   ZZ = H(NA,J)
   H(NA,J) = Q * ZZ + P * H(EN,J)
   H(EN,J) = Q * H(EN,J) - P * ZZ
END DO
!     ********** COLUMN MODIFICATION **********
DO I = 1, EN
   ZZ = H(I,NA)
   H(I,NA) = Q * ZZ + P * H(I,EN)
   H(I,EN) = Q * H(I,EN) - P * ZZ
END DO
!     ********** ACCUMULATE TRANSFORMATIONS **********
DO I = LOW, IGH
   ZZ = Z(I,NA)
   Z(I,NA) = Q * ZZ + P * Z(I,EN)
   Z(I,EN) = Q * Z(I,EN) - P * ZZ
END DO
!
GO TO 330
!     ********** COMPLEX PAIR **********
320 WR(NA) = X + P
WR(EN) = X + P
WI(NA) = ZZ
WI(EN) = -ZZ
330 EN = ENM2
GO TO 60
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
340 IF (NORM .EQ. 0.D0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 1 DO -- **********
do 800 NN = 1, N
   EN = N + 1 - NN
   P = WR(EN)
   Q = WI(EN)
   NA = EN - 1
   IF (Q) 710, 600, 800
!     ********** REAL VECTOR **********
600 M = EN
   H(EN,EN) = 1.D0
   IF (NA .EQ. 0) GO TO 800
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   do 700 II = 1, NA
      I = EN - II
      W = H(I,I) - P
      R = H(I,EN)
      IF (M .GT. NA) GO TO 620
!
      do 610 J = M, NA
610 R = R + H(I,J) * H(J,EN)
!
620 IF (WI(I) .GE. 0.D0) GO TO 630
      ZZ = W
      S = R
      GO TO 700
630 M = I
      IF (WI(I) .NE. 0.D0) GO TO 640
      T = W
      IF (W .EQ. 0.D0) T = MACHEP * NORM
      H(I,EN) = -R / T
      GO TO 700
!     ********** SOLVE REAL EQUATIONS **********
640 X = H(I,I+1)
      Y = H(I+1,I)
      Q = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I)
      T = (X * S - ZZ * R) / Q
      H(I,EN) = T
      IF (DABS(X) .LE. DABS(ZZ)) GO TO 650
      H(I+1,EN) = (-R - W * T) / X
      GO TO 700
650 H(I+1,EN) = (-S - Y * T) / ZZ
700 CONTINUE
!     ********** END REAL VECTOR **********
   GO TO 800
!     ********** COMPLEX VECTOR **********
710 M = NA
!     ********** LAST VECTOR COMPONENT CHOSEN IMAGINARY SO THAT
!                EIGENVECTOR MATRIX IS TRIANGULAR **********
   IF (DABS(H(EN,NA)) .LE. DABS(H(NA,EN))) GO TO 720
   H(NA,NA) = Q / H(EN,NA)
   H(NA,EN) = -(H(EN,EN) - P) / H(EN,NA)
   GO TO 730
720 U = H(NA,NA) - P
   B = -H(NA,EN) / (U * U + Q * Q)
   H(NA,NA) = B * Q
   H(NA,EN) = B * U
730 H(EN,NA) = 0.D0
   H(EN,EN) = 1.D0
   ENM2 = NA - 1
   IF (ENM2 .EQ. 0) GO TO 800
!     ********** FOR I=EN-2 STEP -1 UNTIL 1 DO -- **********
   do 790 II = 1, ENM2
      I = NA - II
      W = H(I,I) - P
      RA = 0.D0
      SA = H(I,EN)
!
      DO J = M, NA
         RA = RA + H(I,J) * H(J,NA)
         SA = SA + H(I,J) * H(J,EN)
      END DO
!
      IF (WI(I) .GE. 0.D0) GO TO 770
      ZZ = W
      R = RA
      S = SA
      GO TO 790
770 M = I
      IF (WI(I) .NE. 0.D0) GO TO 780
      D = W * W + Q * Q
      H(I,NA) = -(RA * W + SA * Q) / D
      H(I,EN) = (RA * Q - SA * W) / D
      GO TO 790
!     ********** SOLVE COMPLEX EQUATIONS **********
780 X = H(I,I+1)
      Y = H(I+1,I)
      VR = (WR(I) - P) * (WR(I) - P) + WI(I) * WI(I) - Q * Q
      VI = (WR(I) - P) * 2.D0 * Q
      IF (VR .EQ. 0.D0 .AND. VI .EQ. 0.D0) VR = MACHEP * NORM &
&* (DABS(W) + DABS(Q) + DABS(X) + DABS(Y) + DABS(ZZ))
      A = X * R - ZZ * RA + Q * SA
      B = X * S - ZZ * SA - Q * RA
      D = VR * VR + VI * VI
      H(I,NA) = (A * VR + B * VI) / D
      H(I,EN) = (B * VR - A * VI) / D
      IF (DABS(X) .LE. DABS(ZZ) + DABS(Q)) GO TO 785
      H(I+1,NA) = (-RA - W * H(I,NA) + Q * H(I,EN)) / X
      H(I+1,EN) = (-SA - W * H(I,EN) - Q * H(I,NA)) / X
      GO TO 790
785 A = -R - Y * H(I,NA)
      B = -S - Y * H(I,EN)
      D = ZZ * ZZ + Q * Q
      H(I+1,NA) = (A * ZZ + B * Q) / D
      H(I+1,EN) = (B * ZZ - A * Q) / D
790 CONTINUE
!     ********** END COMPLEX VECTOR **********
800 CONTINUE
!     ********** END BACK SUBSTITUTION.
!                VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
!
   do 820 J = I, N
820 Z(I,J) = H(I,J)
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW DO -- **********
do 880 JJ = LOW, N
   J = N + LOW - JJ
   M = MIN0(J,IGH)
!
   do 880 I = LOW, IGH
      ZZ = 0.D0
!
      do 860 K = LOW, M
860 ZZ = ZZ + Z(I,K) * H(K,J)
!
      Z(I,J) = ZZ
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE DHQR2

SUBROUTINE SEIG (A, KA, N, W, T, IERR)
IMPLICIT NONE
INTEGER IERR, KA, N
INTEGER L
!-----------------------------------------------------------------------
!               EIGENVALUES OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(*), W(N), T(*)
!
IF (KA .EQ. 0) GO TO 10
   CALL TRED1 (KA, N, A, W, T(N+1), T(1))
   CALL TQLRAT (N, W, T, IERR)
   RETURN
10 L = N*(N + 1)
L = L/2
CALL TRED3 (N, L, A, W, T(N+1), T(1))
CALL TQLRAT (N, W, T, IERR)
RETURN
END SUBROUTINE SEIG

SUBROUTINE SEIG1 (A, KA, N, W, T, IERR)
IMPLICIT NONE
INTEGER IERR, KA, N
INTEGER L
!-----------------------------------------------------------------------
!               EIGENVALUES OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(*), W(N), T(N)
!
IF (KA .EQ. 0) GO TO 10
   CALL TRED1 (KA, N, A, W, T, T)
   CALL IMTQL1 (N, W, T, IERR)
   RETURN
10 L = N*(N + 1)
L = L/2
CALL TRED3 (N, L, A, W, T, T)
CALL IMTQL1 (N, W, T, IERR)
RETURN
END SUBROUTINE SEIG1

SUBROUTINE SEIGV (A, KA, N, W, Z, T, IERR)
IMPLICIT NONE
INTEGER IERR, KA, N
!-----------------------------------------------------------------------
!        EIGENVALUES AND EIGENVECTORS OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), W(N), Z(KA,N), T(N)
!
CALL TRED2 (KA, N, A, W, T, Z)
CALL TQL2 (KA, N, W, T, Z, IERR)
RETURN
END SUBROUTINE SEIGV

SUBROUTINE SEIGV1 (A, KA, N, W, Z, T, IERR)
IMPLICIT NONE
INTEGER IERR, KA, N
!-----------------------------------------------------------------------
!        EIGENVALUES AND EIGENVECTORS OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
REAL A(KA,N), W(N), Z(KA,N), T(N)
!
CALL TRED2 (KA, N, A, W, T, Z)
CALL IMTQL2 (KA, N, W, T, Z, IERR)
RETURN
END SUBROUTINE SEIGV1

SUBROUTINE TRED1(NM,N,A,D,E,E2)
IMPLICIT NONE
!
INTEGER I,J,K,L,N,II,NM,JP1
REAL A(NM,N),D(N),E(N),E2(N)
REAL F,G,H,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED1,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX
!     TO A SYMMETRIC TRIDIAGONAL MATRIX USING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION IN ITS STRICT LOWER
!          TRIANGLE.  THE FULL UPPER TRIANGLE OF A IS UNALTERED,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
100 D(I) = A(I,I)
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + ABS(A(I,K))
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = 0.0
   E2(I) = 0.0
   GO TO 290
!
140 DO K = 1, L
      A(I,K) = A(I,K) / SCALE
      H = H + A(I,K) * A(I,K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = A(I,L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   A(I,L) = F - G
   IF (L .EQ. 1) GO TO 270
   F = 0.0
!
   DO J = 1, L
      G = 0.0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + A(J,K) * A(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + A(K,J) * A(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * A(I,J)
   END DO
!
   H = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = A(I,J)
      G = E(J) - H * F
      E(J) = G
!
      do 260 K = 1, J
         A(J,K) = A(J,K) - F * E(K) - G * A(I,K)
260 CONTINUE
!
270 do 280 K = 1, L
280 A(I,K) = SCALE * A(I,K)
!
290 H = D(I)
   D(I) = A(I,I)
   A(I,I) = H
END DO
!
RETURN
!     ********** LAST CARD OF TRED1 **********
END SUBROUTINE TRED1

SUBROUTINE TRED3(N,NV,A,D,E,E2)
!
INTEGER I,J,K,L,N,II,IZ,JK,NV
REAL A(NV),D(N),E(N),E2(N)
REAL F,G,H,HH,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED3,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX, STORED AS
!     A ONE-DIMENSIONAL ARRAY, TO A SYMMETRIC TRIDIAGONAL MATRIX
!     USING ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        NV MUST BE SET TO THE DIMENSION OF THE ARRAY PARAMETER A
!          AS DECLARED IN THE CALLING PROGRAM DIMENSION STATEMENT,
!
!        A CONTAINS THE LOWER TRIANGLE OF THE REAL SYMMETRIC
!          INPUT MATRIX, STORED ROW-WISE AS A ONE-DIMENSIONAL
!          ARRAY, IN ITS FIRST N*(N+1)/2 POSITIONS.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL
!          TRANSFORMATIONS USED IN THE REDUCTION,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   IZ = (I * L) / 2
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   DO K = 1, L
      IZ = IZ + 1
      D(K) = A(IZ)
      SCALE = SCALE + ABS(D(K))
   END DO
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = 0.0
   E2(I) = 0.0
   GO TO 290
!
140 DO K = 1, L
      D(K) = D(K) / SCALE
      H = H + D(K) * D(K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = D(L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   D(L) = F - G
   A(IZ) = SCALE * D(L)
   IF (L .EQ. 1) GO TO 290
   F = 0.0
!
   DO J = 1, L
      G = 0.0
      JK = (J * (J-1)) / 2
!     ********** FORM ELEMENT OF A*U **********
      DO K = 1, L
         JK = JK + 1
         IF (K .GT. J) JK = JK + K - 2
         G = G + A(JK) * D(K)
      END DO
!     ********** FORM ELEMENT OF P **********
      E(J) = G / H
      F = F + E(J) * D(J)
   END DO
!
   HH = F / (H + H)
   JK = 0
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = D(J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         JK = JK + 1
         A(JK) = A(JK) - F * E(K) - G * D(K)
260 CONTINUE
!
290 D(I) = A(IZ+1)
   A(IZ+1) = SCALE * SQRT(H)
END DO
!
RETURN
!     ********** LAST CARD OF TRED3 **********
END SUBROUTINE TRED3

SUBROUTINE TQLRAT(N,D,E2,IERR)
IMPLICIT NONE
REAL SPMPAR
!
INTEGER I,J,L,M,N,II,L1,MML,IERR
REAL D(N),E2(N)
REAL B,C,F,G,H,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQLRAT,
!     ALGORITHM 464, COMM. ACM 16, 689(1973) BY REINSCH.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A SYMMETRIC
!     TRIDIAGONAL MATRIX BY THE RATIONAL QL METHOD.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E2 CONTAINS THE SQUARES OF THE SUBDIAGONAL ELEMENTS OF THE
!          INPUT MATRIX IN ITS LAST N-1 POSITIONS.  E2(1) IS ARBITRARY.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT AND
!          ORDERED FOR INDICES 1,2,...IERR-1, BUT MAY NOT BE
!          THE SMALLEST EIGENVALUES,
!
!        E2 HAS BEEN DESTROYED,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E2(I-1) = E2(I)
!
F = 0.0
B = 0.0
E2(N) = 0.0
!
DO L = 1, N
   J = 0
   H = MACHEP * (ABS(D(L)) + SQRT(E2(L)))
   IF (B .GT. H) GO TO 105
   B = H
   C = B * B
!     ********** LOOK FOR SMALL SQUARED SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (E2(M) .LE. C) GO TO 120
!     ********** E2(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 210
130 IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   S = SQRT(E2(L))
   G = D(L)
   P = (D(L1) - G) / (2.0 * S)
   R = SQRT(P*P+1.0)
   IF (P .LT. 0.0) R = -R
   D(L) = S / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** RATIONAL QL TRANSFORMATION **********
   G = D(M)
   IF (G .EQ. 0.0) G = B
   H = G
   S = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      P = G * H
      R = P + E2(I)
      E2(I+1) = S * R
      S = E2(I) / R
      D(I+1) = H + S * (H + D(I))
      G = D(I) - E2(I) / G
      IF (G .EQ. 0.0) G = B
      H = G * P / R
   END DO
!
   E2(L) = S * G
   D(L) = H
!     ********** GUARD AGAINST UNDERFLOW IN CONVERGENCE TEST **********
   IF (H .EQ. 0.0) GO TO 210
   IF (ABS(E2(L)) .LE. ABS(C/H)) GO TO 210
   E2(L) = H * E2(L)
   IF (E2(L) .NE. 0.0) GO TO 130
210 P = D(L) + F
!     ********** ORDER EIGENVALUES **********
   IF (L .EQ. 1) GO TO 250
!     ********** FOR I=L STEP -1 UNTIL 2 DO -- **********
   DO II = 2, L
      I = L + 2 - II
      IF (P .GE. D(I-1)) GO TO 270
      D(I) = D(I-1)
   END DO
!
250 I = 1
270 D(I) = P
END DO
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF TQLRAT **********
END SUBROUTINE TQLRAT

SUBROUTINE IMTQL1(N,D,E,IERR)
IMPLICIT NONE
REAL SPMPAR
!
INTEGER I,J,L,M,N,II,MML,IERR
REAL D(N),E(N)
REAL B,C,F,G,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE IMTQL1,
!     NUM. MATH. 12, 377-383(1968) BY MARTIN AND WILKINSON,
!     AS MODIFIED IN NUM. MATH. 15, 450(1970) BY DUBRULLE.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 241-248(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A SYMMETRIC
!     TRIDIAGONAL MATRIX BY THE IMPLICIT QL METHOD.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT AND
!          ORDERED FOR INDICES 1,2,...IERR-1, BUT MAY NOT BE
!          THE SMALLEST EIGENVALUES,
!
!        E HAS BEEN DESTROYED,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
E(N) = 0.0
!
DO L = 1, N
   J = 0
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (M .EQ. N) GO TO 120
      IF (ABS(E(M)) .LE. MACHEP * (ABS(D(M)) + ABS(D(M+1)))) &
&GO TO 120
   END DO
!
120 P = D(L)
   IF (M .EQ. L) GO TO 215
   IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   G = (D(L+1) - P) / (2.0 * E(L))
   R = SQRT(G*G+1.0)
   IF (G .LT. 0.0) R = -R
   G = D(M) - P + E(L) / (G + R)
   S = 1.0
   C = 1.0
   P = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      F = S * E(I)
      B = C * E(I)
      IF (ABS(F) .LT. ABS(G)) GO TO 150
      C = G / F
      R = SQRT(C*C+1.0)
      E(I+1) = F * R
      S = 1.0 / R
      C = C * S
      GO TO 160
150 S = F / G
      R = SQRT(S*S+1.0)
      E(I+1) = G * R
      C = 1.0 / R
      S = S * C
160 G = D(I+1) - P
      R = (D(I) - G) * S + 2.0 * C * B
      P = S * R
      D(I+1) = G + P
      G = C * R - B
   END DO
!
   D(L) = D(L) - P
   E(L) = G
   E(M) = 0.0
   GO TO 105
!     ********** ORDER EIGENVALUES **********
215 IF (L .EQ. 1) GO TO 250
!     ********** FOR I=L STEP -1 UNTIL 2 DO -- **********
   DO II = 2, L
      I = L + 2 - II
      IF (P .GE. D(I-1)) GO TO 270
      D(I) = D(I-1)
   END DO
!
250 I = 1
270 D(I) = P
END DO
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF IMTQL1 **********
END SUBROUTINE IMTQL1

SUBROUTINE TRED2(NM,N,A,D,E,Z)
IMPLICIT NONE
!
INTEGER I,J,K,L,N,II,NM,JP1
REAL A(NM,N),D(N),E(N),Z(NM,N)
REAL F,G,H,HH,SCALE
!     REAL SQRT,ABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED2,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX TO A
!     SYMMETRIC TRIDIAGONAL MATRIX USING AND ACCUMULATING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        Z CONTAINS THE ORTHOGONAL TRANSFORMATION MATRIX
!          PRODUCED IN THE REDUCTION,
!
!        A AND Z MAY COINCIDE.  IF DISTINCT, A IS UNALTERED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
!
   do 100 J = 1, I
      Z(I,J) = A(I,J)
100 CONTINUE
!
IF (N .EQ. 1) GO TO 320
!     ********** FOR I=N STEP -1 UNTIL 2 DO -- **********
DO II = 2, N
   I = N + 2 - II
   L = I - 1
   H = 0.0
   SCALE = 0.0
   IF (L .LT. 2) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + ABS(Z(I,K))
!
   IF (SCALE .NE. 0.0) GO TO 140
130 E(I) = Z(I,L)
   GO TO 290
!
140 DO K = 1, L
      Z(I,K) = Z(I,K) / SCALE
      H = H + Z(I,K) * Z(I,K)
   END DO
!
   F = Z(I,L)
   G = SQRT(H)
   IF (F .GE. 0.0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   Z(I,L) = F - G
   F = 0.0
!
   DO J = 1, L
      Z(J,I) = Z(I,J) / H
      G = 0.0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + Z(J,K) * Z(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + Z(K,J) * Z(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * Z(I,J)
   END DO
!
   HH = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = Z(I,J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         Z(J,K) = Z(J,K) - F * E(K) - G * Z(I,K)
260 CONTINUE
!
290 D(I) = H
END DO
!
320 D(1) = 0.0
E(1) = 0.0
!     ********** ACCUMULATION OF TRANSFORMATION MATRICES **********
do 500 I = 1, N
   L = I - 1
   IF (D(I) .EQ. 0.0) GO TO 380
!
   do 360 J = 1, L
      G = 0.0
!
      do 340 K = 1, L
340 G = G + Z(I,K) * Z(K,J)
!
      do 360 K = 1, L
         Z(K,J) = Z(K,J) - G * Z(K,I)
360 CONTINUE
!
380 D(I) = Z(I,I)
   Z(I,I) = 1.0
   IF (L .LT. 1) GO TO 500
!
   DO J = 1, L
      Z(I,J) = 0.0
      Z(J,I) = 0.0
   END DO
!
500 CONTINUE
!
RETURN
!     ********** LAST CARD OF TRED2 **********
END SUBROUTINE TRED2

SUBROUTINE TQL2(NM,N,D,E,Z,IERR)
IMPLICIT NONE
REAL SPMPAR
!
INTEGER I,J,K,L,M,N,II,L1,NM,MML,IERR
REAL D(N),E(N),Z(NM,N)
REAL B,C,F,G,H,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQL2,
!     NUM. MATH. 11, 293-306(1968) BY BOWDLER, MARTIN, REINSCH, AND
!     WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 227-240(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A SYMMETRIC TRIDIAGONAL MATRIX BY THE QL METHOD.
!     THE EIGENVECTORS OF A FULL SYMMETRIC MATRIX CAN ALSO
!     BE FOUND IF  TRED2  HAS BEEN USED TO REDUCE THIS
!     FULL MATRIX TO TRIDIAGONAL FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  TRED2, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE TRIDIAGONAL MATRIX ARE DESIRED, Z MUST CONTAIN
!          THE IDENTITY MATRIX.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT BUT
!          UNORDERED FOR INDICES 1,2,...,IERR-1,
!
!        E HAS BEEN DESTROYED,
!
!        Z CONTAINS ORTHONORMAL EIGENVECTORS OF THE SYMMETRIC
!          TRIDIAGONAL (OR FULL) MATRIX.  IF AN ERROR EXIT IS MADE,
!          Z CONTAINS THE EIGENVECTORS ASSOCIATED WITH THE STORED
!          EIGENVALUES,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
F = 0.0
B = 0.0
E(N) = 0.0
!
DO L = 1, N
   J = 0
   H = MACHEP * (ABS(D(L)) + ABS(E(L)))
   IF (B .LT. H) B = H
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
   DO M = L, N
      IF (ABS(E(M)) .LE. B) GO TO 120
!     ********** E(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 220
130 IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   G = D(L)
   P = (D(L1) - G) / (2.0 * E(L))
   R = SQRT(P*P+1.0)
   IF (P .LT. 0.0) R = -R
   D(L) = E(L) / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** QL TRANSFORMATION **********
   P = D(M)
   C = 1.0
   S = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      G = C * E(I)
      H = C * P
      IF (ABS(P) .LT. ABS(E(I))) GO TO 150
      C = E(I) / P
      R = SQRT(C*C+1.0)
      E(I+1) = S * P * R
      S = C / R
      C = 1.0 / R
      GO TO 160
150 C = P / E(I)
      R = SQRT(C*C+1.0)
      E(I+1) = S * E(I) * R
      S = 1.0 / R
      C = C * S
160 P = C * D(I) - S * G
      D(I+1) = H + S * (C * G + S * D(I))
!     ********** FORM VECTOR **********
      DO K = 1, N
         H = Z(K,I+1)
         Z(K,I+1) = S * Z(K,I) + C * H
         Z(K,I) = C * Z(K,I) - S * H
      END DO
!
   END DO
!
   E(L) = S * P
   D(L) = C * P
   IF (ABS(E(L)) .GT. B) GO TO 130
220 D(L) = D(L) + F
END DO
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 II = 2, N
   I = II - 1
   K = I
   P = D(I)
!
   do 260 J = II, N
      IF (D(J) .GE. P) GO TO 260
      K = J
      P = D(J)
260 CONTINUE
!
   IF (K .EQ. I) GO TO 300
   D(K) = D(I)
   D(I) = P
!
   DO J = 1, N
      P = Z(J,I)
      Z(J,I) = Z(J,K)
      Z(J,K) = P
   END DO
!
300 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF TQL2 **********
END SUBROUTINE TQL2

SUBROUTINE IMTQL2(NM,N,D,E,Z,IERR)
IMPLICIT NONE
REAL SPMPAR
!
INTEGER I,J,K,L,M,N,II,NM,MML,IERR
REAL D(N),E(N),Z(NM,N)
REAL B,C,F,G,P,R,S,MACHEP
!     REAL SQRT,ABS,SPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE IMTQL2,
!     NUM. MATH. 12, 377-383(1968) BY MARTIN AND WILKINSON,
!     AS MODIFIED IN NUM. MATH. 15, 450(1970) BY DUBRULLE.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 241-248(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A SYMMETRIC TRIDIAGONAL MATRIX BY THE IMPLICIT QL METHOD.
!     THE EIGENVECTORS OF A FULL SYMMETRIC MATRIX CAN ALSO
!     BE FOUND IF  TRED2  HAS BEEN USED TO REDUCE THIS
!     FULL MATRIX TO TRIDIAGONAL FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  TRED2, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE TRIDIAGONAL MATRIX ARE DESIRED, Z MUST CONTAIN
!          THE IDENTITY MATRIX.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT BUT
!          UNORDERED FOR INDICES 1,2,...,IERR-1,
!
!        E HAS BEEN DESTROYED,
!
!        Z CONTAINS ORTHONORMAL EIGENVECTORS OF THE SYMMETRIC
!          TRIDIAGONAL (OR FULL) MATRIX.  IF AN ERROR EXIT IS MADE,
!          Z CONTAINS THE EIGENVECTORS ASSOCIATED WITH THE STORED
!          EIGENVALUES,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
E(N) = 0.0
!
do 240 L = 1, N
   J = 0
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (M .EQ. N) GO TO 120
      IF (ABS(E(M)) .LE. MACHEP * (ABS(D(M)) + ABS(D(M+1)))) &
&GO TO 120
   END DO
!
120 P = D(L)
   IF (M .EQ. L) GO TO 240
   IF (J .EQ. 30) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   G = (D(L+1) - P) / (2.0 * E(L))
   R = SQRT(G*G+1.0)
   IF (G .LT. 0.0) R = -R
   G = D(M) - P + E(L) / (G + R)
   S = 1.0
   C = 1.0
   P = 0.0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      F = S * E(I)
      B = C * E(I)
      IF (ABS(F) .LT. ABS(G)) GO TO 150
      C = G / F
      R = SQRT(C*C+1.0)
      E(I+1) = F * R
      S = 1.0 / R
      C = C * S
      GO TO 160
150 S = F / G
      R = SQRT(S*S+1.0)
      E(I+1) = G * R
      C = 1.0 / R
      S = S * C
160 G = D(I+1) - P
      R = (D(I) - G) * S + 2.0 * C * B
      P = S * R
      D(I+1) = G + P
      G = C * R - B
!     ********** FORM VECTOR **********
      DO K = 1, N
         F = Z(K,I+1)
         Z(K,I+1) = S * Z(K,I) + C * F
         Z(K,I) = C * Z(K,I) - S * F
      END DO
!
   END DO
!
   D(L) = D(L) - P
   E(L) = G
   E(M) = 0.0
   GO TO 105
240 CONTINUE
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 II = 2, N
   I = II - 1
   K = I
   P = D(I)
!
   do 260 J = II, N
      IF (D(J) .GE. P) GO TO 260
      K = J
      P = D(J)
260 CONTINUE
!
   IF (K .EQ. I) GO TO 300
   D(K) = D(I)
   D(I) = P
!
   DO J = 1, N
      P = Z(J,I)
      Z(J,I) = Z(J,K)
      Z(J,K) = P
   END DO
!
300 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF IMTQL2 **********
END SUBROUTINE IMTQL2

SUBROUTINE DSEIG (A, KA, N, W, T, IERR)
!-----------------------------------------------------------------------
!                DOUBLE PRECISION COMPUTATION OF THE
!               EIGENVALUES OF SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(*), W(N), T(*)
!
IF (KA .EQ. 0) GO TO 10
   CALL DTRED1 (KA, N, A, W, T(N+1), T(1))
   CALL DTQL (N, W, T, IERR)
   RETURN
10 L = N*(N + 1)
L = L/2
CALL DTRED3 (N, L, A, W, T(N+1), T(1))
CALL DTQL (N, W, T, IERR)
RETURN
END SUBROUTINE DSEIG

SUBROUTINE DSEIGV (A, KA, N, W, Z, T, IERR)
!-----------------------------------------------------------------------
!                 DOUBLE PRECISION COMPUTATION OF
!                 EIGENVALUES AND EIGENVECTORS OF
!                     SYMMETRIC REAL MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION A(KA,N), W(N), Z(KA,N), T(N)
!
CALL DTRED2 (KA, N, A, W, T, Z)
CALL DTQL2 (KA, N, W, T, Z, IERR)
RETURN
END SUBROUTINE DSEIGV

SUBROUTINE DTRED1 (NM,N,A,D,E,E2)
!
INTEGER I,J,K,L,N,II,NM,JP1
DOUBLE PRECISION A(NM,N),D(N),E(N),E2(N)
DOUBLE PRECISION F,G,H,SCALE
!     DOUBLE PRECISION DSQRT,DABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED1,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX
!     TO A SYMMETRIC TRIDIAGONAL MATRIX USING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL TRANS-
!          FORMATIONS USED IN THE REDUCTION IN ITS STRICT LOWER
!          TRIANGLE.  THE FULL UPPER TRIANGLE OF A IS UNALTERED,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
100 D(I) = A(I,I)
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   H = 0.D0
   SCALE = 0.D0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + DABS(A(I,K))
!
   IF (SCALE .NE. 0.D0) GO TO 140
130 E(I) = 0.D0
   E2(I) = 0.D0
   GO TO 290
!
140 DO K = 1, L
      A(I,K) = A(I,K) / SCALE
      H = H + A(I,K) * A(I,K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = A(I,L)
   G = DSQRT(H)
   IF (F .GE. 0.D0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   A(I,L) = F - G
   IF (L .EQ. 1) GO TO 270
   F = 0.D0
!
   DO J = 1, L
      G = 0.D0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + A(J,K) * A(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + A(K,J) * A(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * A(I,J)
   END DO
!
   H = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = A(I,J)
      G = E(J) - H * F
      E(J) = G
!
      do 260 K = 1, J
         A(J,K) = A(J,K) - F * E(K) - G * A(I,K)
260 CONTINUE
!
270 do 280 K = 1, L
280 A(I,K) = SCALE * A(I,K)
!
290 H = D(I)
   D(I) = A(I,I)
   A(I,I) = H
END DO
!
RETURN
!     ********** LAST CARD OF DTRED1 **********
END SUBROUTINE DTRED1

SUBROUTINE DTRED3 (N,NV,A,D,E,E2)
!
INTEGER I,J,K,L,N,II,IZ,JK,NV
DOUBLE PRECISION A(NV),D(N),E(N),E2(N)
DOUBLE PRECISION F,G,H,HH,SCALE
!     DOUBLE PRECISION DSQRT,DABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED3,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX, STORED AS
!     A ONE-DIMENSIONAL ARRAY, TO A SYMMETRIC TRIDIAGONAL MATRIX
!     USING ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        NV MUST BE SET TO THE DIMENSION OF THE ARRAY PARAMETER A
!          AS DECLARED IN THE CALLING PROGRAM DIMENSION STATEMENT,
!
!        A CONTAINS THE LOWER TRIANGLE OF THE REAL SYMMETRIC
!          INPUT MATRIX, STORED ROW-WISE AS A ONE-DIMENSIONAL
!          ARRAY, IN ITS FIRST N*(N+1)/2 POSITIONS.
!
!     ON OUTPUT-
!
!        A CONTAINS INFORMATION ABOUT THE ORTHOGONAL
!          TRANSFORMATIONS USED IN THE REDUCTION,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        E2 CONTAINS THE SQUARES OF THE CORRESPONDING ELEMENTS OF E.
!          E2 MAY COINCIDE WITH E IF THE SQUARES ARE NOT NEEDED.
!
!-----------------------------------------------------------------------
!
!     ********** FOR I=N STEP -1 UNTIL 1 DO -- **********
DO II = 1, N
   I = N + 1 - II
   L = I - 1
   IZ = (I * L) / 2
   H = 0.D0
   SCALE = 0.D0
   IF (L .LT. 1) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   DO K = 1, L
      IZ = IZ + 1
      D(K) = A(IZ)
      SCALE = SCALE + DABS(D(K))
   END DO
!
   IF (SCALE .NE. 0.D0) GO TO 140
130 E(I) = 0.D0
   E2(I) = 0.D0
   GO TO 290
!
140 DO K = 1, L
      D(K) = D(K) / SCALE
      H = H + D(K) * D(K)
   END DO
!
   E2(I) = SCALE * SCALE * H
   F = D(L)
   G = DSQRT(H)
   IF (F .GE. 0.D0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   D(L) = F - G
   A(IZ) = SCALE * D(L)
   IF (L .EQ. 1) GO TO 290
   F = 0.D0
!
   DO J = 1, L
      G = 0.D0
      JK = (J * (J-1)) / 2
!     ********** FORM ELEMENT OF A*U **********
      DO K = 1, L
         JK = JK + 1
         IF (K .GT. J) JK = JK + K - 2
         G = G + A(JK) * D(K)
      END DO
!     ********** FORM ELEMENT OF P **********
      E(J) = G / H
      F = F + E(J) * D(J)
   END DO
!
   HH = F / (H + H)
   JK = 0
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = D(J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         JK = JK + 1
         A(JK) = A(JK) - F * E(K) - G * D(K)
260 CONTINUE
!
290 D(I) = A(IZ+1)
   A(IZ+1) = SCALE * DSQRT(H)
END DO
!
RETURN
!     ********** LAST CARD OF DTRED3 **********
END SUBROUTINE DTRED3

SUBROUTINE DTQL (N,D,E2,IERR)
!
INTEGER I,J,L,M,N,II,L1,MML,IERR
DOUBLE PRECISION D(N),E2(N)
DOUBLE PRECISION B,C,F,G,H,P,R,S,MACHEP
DOUBLE PRECISION DPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQLRAT,
!     ALGORITHM 464, COMM. ACM 16, 689(1973) BY REINSCH.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A SYMMETRIC
!     TRIDIAGONAL MATRIX BY THE RATIONAL QL METHOD.
!
!     ON INPUT-
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E2 CONTAINS THE SQUARES OF THE SUBDIAGONAL ELEMENTS OF THE
!          INPUT MATRIX IN ITS LAST N-1 POSITIONS.  E2(1) IS ARBITRARY.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT AND
!          ORDERED FOR INDICES 1,2,...IERR-1, BUT MAY NOT BE
!          THE SMALLEST EIGENVALUES,
!
!        E2 HAS BEEN DESTROYED,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E2(I-1) = E2(I)
!
F = 0.D0
B = 0.D0
E2(N) = 0.D0
!
DO L = 1, N
   J = 0
   H = MACHEP * (DABS(D(L)) + DSQRT(E2(L)))
   IF (B .GT. H) GO TO 105
   B = H
   C = B * B
!     ********** LOOK FOR SMALL SQUARED SUB-DIAGONAL ELEMENT **********
105 DO M = L, N
      IF (E2(M) .LE. C) GO TO 120
!     ********** E2(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 210
130 IF (J .EQ. 50) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   S = DSQRT(E2(L))
   G = D(L)
   P = (D(L1) - G) / (2.D0 * S)
   R = DSQRT(P*P + 1.D0)
   IF (P .LT. 0.D0) R = -R
   D(L) = S / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** RATIONAL QL TRANSFORMATION **********
   G = D(M)
   IF (G .EQ. 0.D0) G = B
   H = G
   S = 0.D0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      P = G * H
      R = P + E2(I)
      E2(I+1) = S * R
      S = E2(I) / R
      D(I+1) = H + S * (H + D(I))
      G = D(I) - E2(I) / G
      IF (G .EQ. 0.D0) G = B
      H = G * P / R
   END DO
!
   E2(L) = S * G
   D(L) = H
!     ********** GUARD AGAINST UNDERFLOW IN CONVERGENCE TEST **********
   IF (H .EQ. 0.D0) GO TO 210
   IF (DABS(E2(L)) .LE. DABS(C/H)) GO TO 210
   E2(L) = H * E2(L)
   IF (E2(L) .NE. 0.D0) GO TO 130
210 P = D(L) + F
!     ********** ORDER EIGENVALUES **********
   IF (L .EQ. 1) GO TO 250
!     ********** FOR I=L STEP -1 UNTIL 2 DO -- **********
   DO II = 2, L
      I = L + 2 - II
      IF (P .GE. D(I-1)) GO TO 270
      D(I) = D(I-1)
   END DO
!
250 I = 1
270 D(I) = P
END DO
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF DTQL **********
END SUBROUTINE DTQL

SUBROUTINE DTRED2 (NM,N,A,D,E,Z)
!
INTEGER I,J,K,L,N,II,NM,JP1
DOUBLE PRECISION A(NM,N),D(N),E(N),Z(NM,N)
DOUBLE PRECISION F,G,H,HH,SCALE
!     DOUBLE PRECISION DSQRT,DABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TRED2,
!     NUM. MATH. 11, 181-195(1968) BY MARTIN, REINSCH, AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 212-226(1971).
!
!     THIS SUBROUTINE REDUCES A REAL SYMMETRIC MATRIX TO A
!     SYMMETRIC TRIDIAGONAL MATRIX USING AND ACCUMULATING
!     ORTHOGONAL SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        A CONTAINS THE REAL SYMMETRIC INPUT MATRIX.  ONLY THE
!          LOWER TRIANGLE OF THE MATRIX NEED BE SUPPLIED.
!
!     ON OUTPUT-
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE TRIDIAGONAL MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE TRIDIAGONAL
!          MATRIX IN ITS LAST N-1 POSITIONS.  E(1) IS SET TO ZERO,
!
!        Z CONTAINS THE ORTHOGONAL TRANSFORMATION MATRIX
!          PRODUCED IN THE REDUCTION,
!
!        A AND Z MAY COINCIDE.  IF DISTINCT, A IS UNALTERED.
!
!-----------------------------------------------------------------------
!
do 100 I = 1, N
!
   do 100 J = 1, I
      Z(I,J) = A(I,J)
100 CONTINUE
!
IF (N .EQ. 1) GO TO 320
!     ********** FOR I=N STEP -1 UNTIL 2 DO -- **********
DO II = 2, N
   I = N + 2 - II
   L = I - 1
   H = 0.D0
   SCALE = 0.D0
   IF (L .LT. 2) GO TO 130
!     ********** SCALE ROW (ALGOL TOL THEN NOT NEEDED) **********
   do 120 K = 1, L
120 SCALE = SCALE + DABS(Z(I,K))
!
   IF (SCALE .NE. 0.D0) GO TO 140
130 E(I) = Z(I,L)
   GO TO 290
!
140 DO K = 1, L
      Z(I,K) = Z(I,K) / SCALE
      H = H + Z(I,K) * Z(I,K)
   END DO
!
   F = Z(I,L)
   G = DSQRT(H)
   IF (F .GE. 0.D0) G = -G
   E(I) = SCALE * G
   H = H - F * G
   Z(I,L) = F - G
   F = 0.D0
!
   DO J = 1, L
      Z(J,I) = Z(I,J) / H
      G = 0.D0
!     ********** FORM ELEMENT OF A*U **********
      do 180 K = 1, J
180 G = G + Z(J,K) * Z(I,K)
!
      JP1 = J + 1
      IF (L .LT. JP1) GO TO 220
!
      do 200 K = JP1, L
200 G = G + Z(K,J) * Z(I,K)
!     ********** FORM ELEMENT OF P **********
220 E(J) = G / H
      F = F + E(J) * Z(I,J)
   END DO
!
   HH = F / (H + H)
!     ********** FORM REDUCED A **********
   do 260 J = 1, L
      F = Z(I,J)
      G = E(J) - HH * F
      E(J) = G
!
      do 260 K = 1, J
         Z(J,K) = Z(J,K) - F * E(K) - G * Z(I,K)
260 CONTINUE
!
290 D(I) = H
END DO
!
320 D(1) = 0.D0
E(1) = 0.D0
!     ********** ACCUMULATION OF TRANSFORMATION MATRICES **********
do 500 I = 1, N
   L = I - 1
   IF (D(I) .EQ. 0.D0) GO TO 380
!
   do 360 J = 1, L
      G = 0.D0
!
      do 340 K = 1, L
340 G = G + Z(I,K) * Z(K,J)
!
      do 360 K = 1, L
         Z(K,J) = Z(K,J) - G * Z(K,I)
360 CONTINUE
!
380 D(I) = Z(I,I)
   Z(I,I) = 1.D0
   IF (L .LT. 1) GO TO 500
!
   DO J = 1, L
      Z(I,J) = 0.D0
      Z(J,I) = 0.D0
   END DO
!
500 CONTINUE
!
RETURN
!     ********** LAST CARD OF DTRED2 **********
END SUBROUTINE DTRED2

SUBROUTINE DTQL2 (NM,N,D,E,Z,IERR)
!
INTEGER I,J,K,L,M,N,II,L1,NM,MML,IERR
DOUBLE PRECISION D(N),E(N),Z(NM,N)
DOUBLE PRECISION B,C,F,G,H,P,R,S,MACHEP
DOUBLE PRECISION DPMPAR
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE TQL2,
!     NUM. MATH. 11, 293-306(1968) BY BOWDLER, MARTIN, REINSCH, AND
!     WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 227-240(1971).
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A SYMMETRIC TRIDIAGONAL MATRIX BY THE QL METHOD.
!     THE EIGENVECTORS OF A FULL SYMMETRIC MATRIX CAN ALSO
!     BE FOUND IF  TRED2  HAS BEEN USED TO REDUCE THIS
!     FULL MATRIX TO TRIDIAGONAL FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        D CONTAINS THE DIAGONAL ELEMENTS OF THE INPUT MATRIX,
!
!        E CONTAINS THE SUBDIAGONAL ELEMENTS OF THE INPUT MATRIX
!          IN ITS LAST N-1 POSITIONS.  E(1) IS ARBITRARY,
!
!        Z CONTAINS THE TRANSFORMATION MATRIX PRODUCED IN THE
!          REDUCTION BY  TRED2, IF PERFORMED.  IF THE EIGENVECTORS
!          OF THE TRIDIAGONAL MATRIX ARE DESIRED, Z MUST CONTAIN
!          THE IDENTITY MATRIX.
!
!      ON OUTPUT-
!
!        D CONTAINS THE EIGENVALUES IN ASCENDING ORDER.  IF AN
!          ERROR EXIT IS MADE, THE EIGENVALUES ARE CORRECT BUT
!          UNORDERED FOR INDICES 1,2,...,IERR-1,
!
!        E HAS BEEN DESTROYED,
!
!        Z CONTAINS ORTHONORMAL EIGENVECTORS OF THE SYMMETRIC
!          TRIDIAGONAL (OR FULL) MATRIX.  IF AN ERROR EXIT IS MADE,
!          Z CONTAINS THE EIGENVECTORS ASSOCIATED WITH THE STORED
!          EIGENVALUES,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER. ASSIGN
!                MACHEP THE VALUE U WHERE U IS THE SMALLEST POSITIVE
!                FLOATING POINT NUMBER SUCH THAT 1.0 + U .GT. 1.0 .
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
IF (N .EQ. 1) GO TO 1001
!
do 100 I = 2, N
100 E(I-1) = E(I)
!
F = 0.D0
B = 0.D0
E(N) = 0.D0
!
DO L = 1, N
   J = 0
   H = MACHEP * (DABS(D(L)) + DABS(E(L)))
   IF (B .LT. H) B = H
!     ********** LOOK FOR SMALL SUB-DIAGONAL ELEMENT **********
   DO M = L, N
      IF (DABS(E(M)) .LE. B) GO TO 120
!     ********** E(N) IS ALWAYS ZERO, SO THERE IS NO EXIT
!                THROUGH THE BOTTOM OF THE LOOP **********
   END DO
!
120 IF (M .EQ. L) GO TO 220
130 IF (J .EQ. 50) GO TO 1000
   J = J + 1
!     ********** FORM SHIFT **********
   L1 = L + 1
   G = D(L)
   P = (D(L1) - G) / (2.D0 * E(L))
   R = DSQRT(P*P + 1.D0)
   IF (P .LT. 0.D0) R = -R
   D(L) = E(L) / (P + R)
   H = G - D(L)
!
   do 140 I = L1, N
140 D(I) = D(I) - H
!
   F = F + H
!     ********** QL TRANSFORMATION **********
   P = D(M)
   C = 1.D0
   S = 0.D0
   MML = M - L
!     ********** FOR I=M-1 STEP -1 UNTIL L DO -- **********
   DO II = 1, MML
      I = M - II
      G = C * E(I)
      H = C * P
      IF (DABS(P) .LT. DABS(E(I))) GO TO 150
      C = E(I) / P
      R = DSQRT(C*C + 1.D0)
      E(I+1) = S * P * R
      S = C / R
      C = 1.D0 / R
      GO TO 160
150 C = P / E(I)
      R = DSQRT(C*C + 1.D0)
      E(I+1) = S * E(I) * R
      S = 1.D0 / R
      C = C * S
160 P = C * D(I) - S * G
      D(I+1) = H + S * (C * G + S * D(I))
!     ********** FORM VECTOR **********
      DO K = 1, N
         H = Z(K,I+1)
         Z(K,I+1) = S * Z(K,I) + C * H
         Z(K,I) = C * Z(K,I) - S * H
      END DO
!
   END DO
!
   E(L) = S * P
   D(L) = C * P
   IF (DABS(E(L)) .GT. B) GO TO 130
220 D(L) = D(L) + F
END DO
!     ********** ORDER EIGENVALUES AND EIGENVECTORS **********
do 300 II = 2, N
   I = II - 1
   K = I
   P = D(I)
!
   do 260 J = II, N
      IF (D(J) .GE. P) GO TO 260
      K = J
      P = D(J)
260 CONTINUE
!
   IF (K .EQ. I) GO TO 300
   D(K) = D(I)
   D(I) = P
!
   DO J = 1, N
      P = Z(J,I)
      Z(J,I) = Z(J,K)
      Z(J,K) = P
   END DO
!
300 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = L
1001 RETURN
!     ********** LAST CARD OF DTQL2 **********
END SUBROUTINE DTQL2

SUBROUTINE CEIG(IBAL,AR,AI,KA,N,WR,WI,IERR)
!-----------------------------------------------------------------------
!                EIGENVALUES OF COMPLEX MATRICES
!-----------------------------------------------------------------------
REAL AR(KA,N), AI(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL CBAL(KA,N,AR,AI,LOW,IGH,WR)
CALL CORTH(KA,N,LOW,IGH,AR,AI,WR,WI)
CALL COMQR(KA,N,LOW,IGH,AR,AI,WR,WI,IERR)
RETURN
END SUBROUTINE CEIG

SUBROUTINE CEIGV(IBAL,AR,AI,KA,N,WR,WI,ZR,ZI,IERR,TEMP)
!-----------------------------------------------------------------------
!          EIGENVALUES AND EIGENVECTORS OF COMPLEX MATRICES
!-----------------------------------------------------------------------
REAL AR(KA,N),AI(KA,N),WR(N),WI(N),ZR(KA,N),ZI(KA,N),TEMP(*)
!----------------------
!     TEMP IS A TEMPORARY STORAGE AREA
!        DIMENSION(TEMP) .GE. 2*N    IF IBAL .EQ. 0
!        DIMENSION(TEMP) .GE. 3*N    IF IBAL .NE. 0
!----------------------
I2 = 1
I3 = N + 1
I1 = N + I3
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL CBAL(KA,N,AR,AI,LOW,IGH,TEMP(I1))
CALL CORTH(KA,N,LOW,IGH,AR,AI,TEMP(I2),TEMP(I3))
CALL COMQR2(KA,N,LOW,IGH,TEMP(I2),TEMP(I3),AR,AI,WR,WI,ZR,ZI,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL CBABK2(KA,N,LOW,IGH,TEMP(I1),N,ZR,ZI)
RETURN
END SUBROUTINE CEIGV

SUBROUTINE CBAL(NM,N,AR,AI,LOW,IGH,SCALE)
!
INTEGER I,J,K,L,M,N,JJ,NM,IGH,LOW,IEXC
REAL AR(NM,N),AI(NM,N),SCALE(N)
REAL C,F,G,R,S,B2,RADIX
!     REAL ABS
LOGICAL NOCONV
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE
!     CBALANCE, WHICH IS A COMPLEX VERSION OF BALANCE,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE BALANCES A COMPLEX MATRIX AND ISOLATES
!     EIGENVALUES WHENEVER POSSIBLE.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX MATRIX TO BE BALANCED.
!
!     ON OUTPUT-
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE BALANCED MATRIX,
!
!        LOW AND IGH ARE TWO INTEGERS SUCH THAT AR(I,J) AND AI(I,J)
!          ARE EQUAL TO ZERO IF
!           (1) I IS GREATER THAN J AND
!           (2) J=1,...,LOW-1 OR I=IGH+1,...,N,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE
!           PERMUTATIONS AND SCALING FACTORS USED.
!
!     SUPPOSE THAT THE PRINCIPAL SUBMATRIX IN ROWS LOW THROUGH IGH
!     HAS BEEN BALANCED, THAT P(J) DENOTES THE INDEX INTERCHANGED
!     WITH J DURING THE PERMUTATION STEP, AND THAT THE ELEMENTS
!     OF THE DIAGONAL MATRIX USED ARE DENOTED BY D(I,J).  THEN
!        SCALE(J) = P(J),    FOR J = 1,...,LOW-1
!                 = D(J,J)       J = LOW,...,IGH
!                 = P(J)         J = IGH+1,...,N.
!     THE ORDER IN WHICH THE INTERCHANGES ARE MADE IS N TO IGH+1,
!     THEN 1 TO LOW-1.
!
!     NOTE THAT 1 IS RETURNED FOR IGH IF IGH IS ZERO FORMALLY.
!
!     THE ALGOL PROCEDURE EXC CONTAINED IN CBALANCE APPEARS IN
!     CBAL  IN LINE.  (NOTE THAT THE ALGOL ROLES OF IDENTIFIERS
!     K,L HAVE BEEN REVERSED.)
!
!-----------------------------------------------------------------------
!
!     ********** RADIX IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE BASE OF THE MACHINE FLOATING POINT REPRESENTATION.
!
           RADIX = IPMPAR(4)
!
!                **********
!
B2 = RADIX * RADIX
K = 1
L = N
GO TO 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 SCALE(M) = J
IF (J .EQ. M) GO TO 50
!
DO I = 1, L
   F = AR(I,J)
   AR(I,J) = AR(I,M)
   AR(I,M) = F
   F = AI(I,J)
   AI(I,J) = AI(I,M)
   AI(I,M) = F
END DO
!
DO I = K, N
   F = AR(J,I)
   AR(J,I) = AR(M,I)
   AR(M,I) = F
   F = AI(J,I)
   AI(J,I) = AI(M,I)
   AI(M,I) = F
END DO
!
50 GO TO (80,130), IEXC
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 IF (L .EQ. 1) GO TO 280
L = L - 1
!     ********** FOR J=L STEP -1 UNTIL 1 DO -- **********
100 do 120 JJ = 1, L
   J = L + 1 - JJ
!
   do 110 I = 1, L
      IF (I .EQ. J) GO TO 110
      IF (AR(J,I) .NE. 0.0 .OR. AI(J,I) .NE. 0.0) GO TO 120
110 CONTINUE
!
   M = L
   IEXC = 1
   GO TO 20
120 CONTINUE
!
GO TO 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 K = K + 1
!
140 do 170 J = K, L
!
   do 150 I = K, L
      IF (I .EQ. J) GO TO 150
      IF (AR(I,J) .NE. 0.0 .OR. AI(I,J) .NE. 0.0) GO TO 170
150 CONTINUE
!
   M = K
   IEXC = 2
   GO TO 20
170 CONTINUE
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS K TO L **********
do 180 I = K, L
180 SCALE(I) = 1.0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 NOCONV = .FALSE.
!
do 270 I = K, L
   C = 0.0
   R = 0.0
!
   do 200 J = K, L
      IF (J .EQ. I) GO TO 200
      C = C + ABS(AR(J,I)) + ABS(AI(J,I))
      R = R + ABS(AR(I,J)) + ABS(AI(I,J))
200 CONTINUE
!     ********** GUARD AGAINST ZERO C OR R DUE TO UNDERFLOW **********
   IF (C .EQ. 0.0 .OR. R .EQ. 0.0) GO TO 270
   G = R / RADIX
   F = 1.0
   S = C + R
210 IF (C .GE. G) GO TO 220
   F = F * RADIX
   C = C * B2
   GO TO 210
220 G = R * RADIX
230 IF (C .LT. G) GO TO 240
   F = F / RADIX
   C = C / B2
   GO TO 230
!     ********** NOW BALANCE **********
240 IF ((C + R) / F .GE. 0.95 * S) GO TO 270
   G = 1.0 / F
   SCALE(I) = SCALE(I) * F
   NOCONV = .TRUE.
!
   DO J = K, N
      AR(I,J) = AR(I,J) * G
      AI(I,J) = AI(I,J) * G
   END DO
!
   DO J = 1, L
      AR(J,I) = AR(J,I) * F
      AI(J,I) = AI(J,I) * F
   END DO
!
270 CONTINUE
!
IF (NOCONV) GO TO 190
!
280 LOW = K
IGH = L
RETURN
!     ********** LAST CARD OF CBAL **********
END SUBROUTINE CBAL

SUBROUTINE CORTH(NM,N,LOW,IGH,AR,AI,ORTR,ORTI)
!
INTEGER I,J,M,N,II,JJ,LA,MP,NM,IGH,KP1,LOW
REAL AR(NM,N),AI(NM,N),ORTR(IGH),ORTI(IGH)
REAL F,G,H,FI,FR,SCALE
!     REAL SQRT,CABS,ABS
!     COMPLEX CMPLX
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A COMPLEX ANALOGUE OF
!     THE ALGOL PROCEDURE ORTHES, NUM. MATH. 12, 349-368(1968)
!     BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A COMPLEX GENERAL MATRIX, THIS SUBROUTINE
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     UNITARY SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  CBAL.  IF  CBAL  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX INPUT MATRIX.
!
!     ON OUTPUT-
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE HESSENBERG MATRIX.  INFORMATION
!          ABOUT THE UNITARY TRANSFORMATIONS USED IN THE REDUCTION
!          IS STORED IN THE REMAINING TRIANGLES UNDER THE
!          HESSENBERG MATRIX,
!
!        ORTR AND ORTI CONTAIN FURTHER INFORMATION ABOUT THE
!          TRANSFORMATIONS.  ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   H = 0.0
   ORTR(M) = 0.0
   ORTI(M) = 0.0
   SCALE = 0.0
!     ********** SCALE COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 I = M, IGH
90 SCALE = SCALE + ABS(AR(I,M-1)) + ABS(AI(I,M-1))
!
   IF (SCALE .EQ. 0.0) GO TO 180
   MP = M + IGH
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
   DO II = M, IGH
      I = MP - II
      ORTR(I) = AR(I,M-1) / SCALE
      ORTI(I) = AI(I,M-1) / SCALE
      H = H + ORTR(I) * ORTR(I) + ORTI(I) * ORTI(I)
   END DO
!
   G = SQRT(H)
   F = CABS(CMPLX(ORTR(M),ORTI(M)))
   IF (F .EQ. 0.0) GO TO 103
   H = H + F * G
   G = G / F
   ORTR(M) = (1.0 + G) * ORTR(M)
   ORTI(M) = (1.0 + G) * ORTI(M)
   GO TO 105
!
103 ORTR(M) = G
   AR(M,M-1) = SCALE
!     ********** FORM (I-(U*UT)/H) * A **********
105 DO J = M, N
      FR = 0.0
      FI = 0.0
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
      DO II = M, IGH
         I = MP - II
         FR = FR + ORTR(I) * AR(I,J) + ORTI(I) * AI(I,J)
         FI = FI + ORTR(I) * AI(I,J) - ORTI(I) * AR(I,J)
      END DO
!
      FR = FR / H
      FI = FI / H
!
      DO I = M, IGH
         AR(I,J) = AR(I,J) - FR * ORTR(I) + FI * ORTI(I)
         AI(I,J) = AI(I,J) - FR * ORTI(I) - FI * ORTR(I)
      END DO
!
   END DO
!     ********** FORM (I-(U*UT)/H)*A*(I-(U*UT)/H) **********
   DO I = 1, IGH
      FR = 0.0
      FI = 0.0
!     ********** FOR J=IGH STEP -1 UNTIL M DO -- **********
      DO JJ = M, IGH
         J = MP - JJ
         FR = FR + ORTR(J) * AR(I,J) - ORTI(J) * AI(I,J)
         FI = FI + ORTR(J) * AI(I,J) + ORTI(J) * AR(I,J)
      END DO
!
      FR = FR / H
      FI = FI / H
!
      DO J = M, IGH
         AR(I,J) = AR(I,J) - FR * ORTR(J) - FI * ORTI(J)
         AI(I,J) = AI(I,J) + FR * ORTI(J) - FI * ORTR(J)
      END DO
!
   END DO
!
   ORTR(M) = SCALE * ORTR(M)
   ORTI(M) = SCALE * ORTI(M)
   AR(M,M-1) = -G * AR(M,M-1)
   AI(M,M-1) = -G * AI(M,M-1)
180 CONTINUE
!
200 RETURN
!     ********** LAST CARD OF CORTH **********
END SUBROUTINE CORTH

SUBROUTINE COMQR(NM,N,LOW,IGH,HR,HI,WR,WI,IERR)
!
INTEGER I,J,L,N,EN,LL,NM,IGH,ITS,LOW,LP1,ENM1,IERR
REAL HR(NM,N),HI(NM,N),WR(N),WI(N)
REAL SI,SR,TI,TR,XI,XR,YI,YR,ZZI,ZZR,NORM,MACHEP
COMPLEX Z3
REAL SPMPAR
!     INTEGER MIN0
!     REAL SQRT,CABS,ABS,REAL,AIMAG
!     COMPLEX CSQRT,CMPLX
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A UNITARY ANALOGUE OF THE
!     ALGOL PROCEDURE  COMLR, NUM. MATH. 12, 369-376(1968) BY MARTIN
!     AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 396-403(1971).
!     THE UNITARY ANALOGUE SUBSTITUTES THE QR ALGORITHM OF FRANCIS
!     (COMP. JOUR. 4, 332-345(1962)) FOR THE LR ALGORITHM.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A COMPLEX
!     UPPER HESSENBERG MATRIX BY THE QR METHOD.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  CBAL.  IF  CBAL  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        HR AND HI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX UPPER HESSENBERG MATRIX.
!          THEIR LOWER TRIANGLES BELOW THE SUBDIAGONAL CONTAIN
!          INFORMATION ABOUT THE UNITARY TRANSFORMATIONS USED IN
!          THE REDUCTION BY  CORTH, IF PERFORMED.
!
!     ON OUTPUT-
!
!        THE UPPER HESSENBERG PORTIONS OF HR AND HI HAVE BEEN
!          DESTROYED.  THEREFORE, THEY MUST BE SAVED BEFORE
!          CALLING  COMQR  IF SUBSEQUENT CALCULATION OF
!          EIGENVECTORS IS TO BE PERFORMED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  IF AN ERROR
!          EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!     ARITHMETIC IS REAL EXCEPT FOR THE REPLACEMENT OF THE ALGOL
!     PROCEDURE CDIV BY COMPLEX DIVISION AND USE OF THE SUBROUTINES
!     CSQRT AND CMPLX IN COMPUTING COMPLEX SQUARE ROOTS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE RELATIVE PRECISION OF FLOATING POINT ARITHMETIC.
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
IF (LOW .EQ. IGH) GO TO 180
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
L = LOW + 1
!
do 170 I = L, IGH
   LL = MIN0(I+1,IGH)
   IF (HI(I,I-1) .EQ. 0.0) GO TO 170
   NORM = CABS(CMPLX(HR(I,I-1),HI(I,I-1)))
   YR = HR(I,I-1) / NORM
   YI = HI(I,I-1) / NORM
   HR(I,I-1) = NORM
   HI(I,I-1) = 0.0
!
   DO J = I, IGH
      SI = YR * HI(I,J) - YI * HR(I,J)
      HR(I,J) = YR * HR(I,J) + YI * HI(I,J)
      HI(I,J) = SI
   END DO
!
   DO J = LOW, LL
      SI = YR * HI(J,I) + YI * HR(J,I)
      HR(J,I) = YR * HR(J,I) - YI * HI(J,I)
      HI(J,I) = SI
   END DO
!
170 CONTINUE
!     ********** STORE ROOTS ISOLATED BY CBAL **********
180 do 200 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 200
   WR(I) = HR(I,I)
   WI(I) = HI(I,I)
200 CONTINUE
!
EN = IGH
TR = 0.0
TI = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 IF (EN .LT. LOW) GO TO 1001
ITS = 0
ENM1 = EN - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW  -- **********
240 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 300
   IF (ABS(HR(L,L-1)) .LE. &
&MACHEP * (ABS(HR(L-1,L-1)) + ABS(HI(L-1,L-1)) &
&+ ABS(HR(L,L)) +ABS(HI(L,L)))) GO TO 300
END DO
!     ********** FORM SHIFT **********
300 IF (L .EQ. EN) GO TO 660
IF (ITS .EQ. 30) GO TO 1000
IF (ITS .EQ. 10 .OR. ITS .EQ. 20) GO TO 320
SR = HR(EN,EN)
SI = HI(EN,EN)
XR = HR(ENM1,EN) * HR(EN,ENM1)
XI = HI(ENM1,EN) * HR(EN,ENM1)
IF (XR .EQ. 0.0 .AND. XI .EQ. 0.0) GO TO 340
YR = (HR(ENM1,ENM1) - SR) / 2.0
YI = (HI(ENM1,ENM1) - SI) / 2.0
Z3 = CSQRT(CMPLX(YR**2-YI**2+XR,2.0*YR*YI+XI))
ZZR = REAL(Z3)
ZZI = AIMAG(Z3)
IF (YR * ZZR + YI * ZZI .GE. 0.0) GO TO 310
ZZR = -ZZR
ZZI = -ZZI
310 Z3 = CMPLX(XR,XI) / CMPLX(YR+ZZR,YI+ZZI)
SR = SR - REAL(Z3)
SI = SI - AIMAG(Z3)
GO TO 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 SR = ABS(HR(EN,ENM1)) + ABS(HR(ENM1,EN-2))
SI = 0.0
!
340 DO I = LOW, EN
   HR(I,I) = HR(I,I) - SR
   HI(I,I) = HI(I,I) - SI
END DO
!
TR = TR + SR
TI = TI + SI
ITS = ITS + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
LP1 = L + 1
!
DO I = LP1, EN
   SR = HR(I,I-1)
   HR(I,I-1) = 0.0
   NORM = SQRT(HR(I-1,I-1)*HR(I-1,I-1)+HI(I-1,I-1)*HI(I-1,I-1) &
&+SR*SR)
   XR = HR(I-1,I-1) / NORM
   WR(I-1) = XR
   XI = HI(I-1,I-1) / NORM
   WI(I-1) = XI
   HR(I-1,I-1) = NORM
   HI(I-1,I-1) = 0.0
   HI(I,I-1) = SR / NORM
!
   DO J = I, EN
      YR = HR(I-1,J)
      YI = HI(I-1,J)
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      HR(I-1,J) = XR * YR + XI * YI + HI(I,I-1) * ZZR
      HI(I-1,J) = XR * YI - XI * YR + HI(I,I-1) * ZZI
      HR(I,J) = XR * ZZR - XI * ZZI - HI(I,I-1) * YR
      HI(I,J) = XR * ZZI + XI * ZZR - HI(I,I-1) * YI
   END DO
!
END DO
!
SI = HI(EN,EN)
IF (SI .EQ. 0.0) GO TO 540
NORM = CABS(CMPLX(HR(EN,EN),SI))
SR = HR(EN,EN) / NORM
SI = SI / NORM
HR(EN,EN) = NORM
HI(EN,EN) = 0.0
!     ********** INVERSE OPERATION (COLUMNS) **********
540 DO J = LP1, EN
   XR = WR(J-1)
   XI = WI(J-1)
!
   DO I = L, J
      YR = HR(I,J-1)
      YI = 0.0
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      IF (I .EQ. J) GO TO 560
      YI = HI(I,J-1)
      HI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
560 HR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      HR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      HI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
END DO
!
IF (SI .EQ. 0.0) GO TO 240
!
DO I = L, EN
   YR = HR(I,EN)
   YI = HI(I,EN)
   HR(I,EN) = SR * YR - SI * YI
   HI(I,EN) = SR * YI + SI * YR
END DO
!
GO TO 240
!     ********** A ROOT FOUND **********
660 WR(EN) = HR(EN,EN) + TR
WI(EN) = HI(EN,EN) + TI
EN = ENM1
GO TO 220
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = EN
1001 RETURN
!     ********** LAST CARD OF COMQR **********
END SUBROUTINE COMQR

SUBROUTINE CBABK2(NM,N,LOW,IGH,SCALE,M,ZR,ZI)
!
INTEGER I,J,K,M,N,II,NM,IGH,LOW
REAL SCALE(N),ZR(NM,M),ZI(NM,M)
REAL S
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE
!     CBABK2, WHICH IS A COMPLEX VERSION OF BALBAK,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE FORMS THE EIGENVECTORS OF A COMPLEX GENERAL
!     MATRIX BY BACK TRANSFORMING THOSE OF THE CORRESPONDING
!     BALANCED MATRIX DETERMINED BY  CBAL.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY  CBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY  CBAL,
!
!        M IS THE NUMBER OF EIGENVECTORS TO BE BACK TRANSFORMED,
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVECTORS TO BE
!          BACK TRANSFORMED IN THEIR FIRST M COLUMNS.
!
!     ON OUTPUT-
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE TRANSFORMED EIGENVECTORS
!          IN THEIR FIRST M COLUMNS.
!
!-----------------------------------------------------------------------
IF (M .EQ. 0) GO TO 200
IF (IGH .EQ. LOW) GO TO 120
!
DO I = LOW, IGH
   S = SCALE(I)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                IF THE FOREGOING STATEMENT IS REPLACED BY
!                S=1.0/SCALE(I). **********
   DO J = 1, M
      ZR(I,J) = ZR(I,J) * S
      ZI(I,J) = ZI(I,J) * S
   END DO
!
END DO
!     ********** FOR I=LOW-1 STEP -1 UNTIL 1,
!                IGH+1 STEP 1 UNTIL N DO -- **********
120 do 140 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 140
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 140
!
   DO J = 1, M
      S = ZR(I,J)
      ZR(I,J) = ZR(K,J)
      ZR(K,J) = S
      S = ZI(I,J)
      ZI(I,J) = ZI(K,J)
      ZI(K,J) = S
   END DO
!
140 CONTINUE
!
200 RETURN
!     ********** LAST CARD OF CBABK2 **********
END SUBROUTINE CBABK2

SUBROUTINE COMQR2(NM,N,LOW,IGH,ORTR,ORTI,HR,HI,WR,WI,ZR,ZI,IERR)
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,NM,NN,IGH,IP1, &
&ITS,LOW,LP1,ENM1,IEND,IERR
REAL HR(NM,N),HI(NM,N),WR(N),WI(N),ZR(NM,N),ZI(NM,N), &
&ORTR(IGH),ORTI(IGH)
REAL SI,SR,TI,TR,XI,XR,YI,YR,ZZI,ZZR,NORM,MACHEP
COMPLEX Z3
REAL SPMPAR
!     INTEGER MIN0
!     REAL SQRT,CABS,ABS,REAL,AIMAG
!     COMPLEX CSQRT,CMPLX
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A UNITARY ANALOGUE OF THE
!     ALGOL PROCEDURE  COMLR2, NUM. MATH. 16, 181-204(1970) BY PETERS
!     AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!     THE UNITARY ANALOGUE SUBSTITUTES THE QR ALGORITHM OF FRANCIS
!     (COMP. JOUR. 4, 332-345(1962)) FOR THE LR ALGORITHM.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS
!     OF A COMPLEX UPPER HESSENBERG MATRIX BY THE QR
!     METHOD.  THE EIGENVECTORS OF A COMPLEX GENERAL MATRIX
!     CAN ALSO BE FOUND IF  CORTH  HAS BEEN USED TO REDUCE
!     THIS GENERAL MATRIX TO HESSENBERG FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE  CBAL.  IF  CBAL  HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        ORTR AND ORTI CONTAIN INFORMATION ABOUT THE UNITARY TRANS-
!          FORMATIONS USED IN THE REDUCTION BY  CORTH, IF PERFORMED.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.  IF THE EIGENVECTORS
!          OF THE HESSENBERG MATRIX ARE DESIRED, SET ORTR(J) AND
!          ORTI(J) TO 0.0 FOR THESE ELEMENTS,
!
!        HR AND HI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX UPPER HESSENBERG MATRIX.
!          THEIR LOWER TRIANGLES BELOW THE SUBDIAGONAL CONTAIN FURTHER
!          INFORMATION ABOUT THE TRANSFORMATIONS WHICH WERE USED IN THE
!          REDUCTION BY  CORTH, IF PERFORMED.  IF THE EIGENVECTORS OF
!          THE HESSENBERG MATRIX ARE DESIRED, THESE ELEMENTS MAY BE
!          ARBITRARY.
!
!     ON OUTPUT-
!
!        ORTR, ORTI, AND THE UPPER HESSENBERG PORTIONS OF HR AND HI
!          HAVE BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  IF AN ERROR
!          EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVECTORS.  THE EIGENVECTORS
!          ARE UNNORMALIZED.  IF AN ERROR EXIT IS MADE, NONE OF
!          THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 30 ITERATIONS.
!
!     ARITHMETIC IS REAL EXCEPT FOR THE REPLACEMENT OF THE ALGOL
!     PROCEDURE CDIV BY COMPLEX DIVISION AND USE OF THE SUBROUTINES
!     CSQRT AND CMPLX IN COMPUTING COMPLEX SQUARE ROOTS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE RELATIVE PRECISION OF FLOATING POINT ARITHMETIC.
!
           MACHEP = SPMPAR(1)
!
!                **********
!
IERR = 0
!     ********** INITIALIZE EIGENVECTOR MATRIX **********
do 100 I = 1, N
!
   do 100 J = 1, N
      ZR(I,J) = 0.0
      ZI(I,J) = 0.0
      IF (I .EQ. J) ZR(I,J) = 1.0
100 CONTINUE
!     ********** FORM THE MATRIX OF ACCUMULATED TRANSFORMATIONS
!                FROM THE INFORMATION LEFT BY CORTH **********
IEND = IGH - LOW - 1
IF (IEND) 180, 150, 105
!     ********** FOR I=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
105 do 140 II = 1, IEND
   I = IGH - II
   IF (ORTR(I) .EQ. 0.0 .AND. ORTI(I) .EQ. 0.0) GO TO 140
   IF (HR(I,I-1) .EQ. 0.0 .AND. HI(I,I-1) .EQ. 0.0) GO TO 140
!     ********** NORM BELOW IS NEGATIVE OF H FORMED IN CORTH **********
   NORM = HR(I,I-1) * ORTR(I) + HI(I,I-1) * ORTI(I)
   IP1 = I + 1
!
   DO K = IP1, IGH
      ORTR(K) = HR(K,I-1)
      ORTI(K) = HI(K,I-1)
   END DO
!
   DO J = I, IGH
      SR = 0.0
      SI = 0.0
!
      DO K = I, IGH
         SR = SR + ORTR(K) * ZR(K,J) + ORTI(K) * ZI(K,J)
         SI = SI + ORTR(K) * ZI(K,J) - ORTI(K) * ZR(K,J)
      END DO
!
      SR = SR / NORM
      SI = SI / NORM
!
      DO K = I, IGH
         ZR(K,J) = ZR(K,J) + SR * ORTR(K) - SI * ORTI(K)
         ZI(K,J) = ZI(K,J) + SR * ORTI(K) + SI * ORTR(K)
      END DO
!
   END DO
!
140 CONTINUE
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
150 L = LOW + 1
!
do 170 I = L, IGH
   LL = MIN0(I+1,IGH)
   IF (HI(I,I-1) .EQ. 0.0) GO TO 170
   NORM = CABS(CMPLX(HR(I,I-1),HI(I,I-1)))
   YR = HR(I,I-1) / NORM
   YI = HI(I,I-1) / NORM
   HR(I,I-1) = NORM
   HI(I,I-1) = 0.0
!
   DO J = I, N
      SI = YR * HI(I,J) - YI * HR(I,J)
      HR(I,J) = YR * HR(I,J) + YI * HI(I,J)
      HI(I,J) = SI
   END DO
!
   DO J = 1, LL
      SI = YR * HI(J,I) + YI * HR(J,I)
      HR(J,I) = YR * HR(J,I) - YI * HI(J,I)
      HI(J,I) = SI
   END DO
!
   DO J = LOW, IGH
      SI = YR * ZI(J,I) + YI * ZR(J,I)
      ZR(J,I) = YR * ZR(J,I) - YI * ZI(J,I)
      ZI(J,I) = SI
   END DO
!
170 CONTINUE
!     ********** STORE ROOTS ISOLATED BY CBAL **********
180 do 200 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 200
   WR(I) = HR(I,I)
   WI(I) = HI(I,I)
200 CONTINUE
!
EN = IGH
TR = 0.0
TI = 0.0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 IF (EN .LT. LOW) GO TO 680
ITS = 0
ENM1 = EN - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
240 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 300
   IF (ABS(HR(L,L-1)) .LE. &
&MACHEP * (ABS(HR(L-1,L-1)) + ABS(HI(L-1,L-1)) &
&+ ABS(HR(L,L)) +ABS(HI(L,L)))) GO TO 300
END DO
!     ********** FORM SHIFT **********
300 IF (L .EQ. EN) GO TO 660
IF (ITS .EQ. 30) GO TO 1000
IF (ITS .EQ. 10 .OR. ITS .EQ. 20) GO TO 320
SR = HR(EN,EN)
SI = HI(EN,EN)
XR = HR(ENM1,EN) * HR(EN,ENM1)
XI = HI(ENM1,EN) * HR(EN,ENM1)
IF (XR .EQ. 0.0 .AND. XI .EQ. 0.0) GO TO 340
YR = (HR(ENM1,ENM1) - SR) / 2.0
YI = (HI(ENM1,ENM1) - SI) / 2.0
Z3 = CSQRT(CMPLX(YR**2-YI**2+XR,2.0*YR*YI+XI))
ZZR = REAL(Z3)
ZZI = AIMAG(Z3)
IF (YR * ZZR + YI * ZZI .GE. 0.0) GO TO 310
ZZR = -ZZR
ZZI = -ZZI
310 Z3 = CMPLX(XR,XI) / CMPLX(YR+ZZR,YI+ZZI)
SR = SR - REAL(Z3)
SI = SI - AIMAG(Z3)
GO TO 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 SR = ABS(HR(EN,ENM1)) + ABS(HR(ENM1,EN-2))
SI = 0.0
!
340 DO I = LOW, EN
   HR(I,I) = HR(I,I) - SR
   HI(I,I) = HI(I,I) - SI
END DO
!
TR = TR + SR
TI = TI + SI
ITS = ITS + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
LP1 = L + 1
!
DO I = LP1, EN
   SR = HR(I,I-1)
   HR(I,I-1) = 0.0
   NORM = SQRT(HR(I-1,I-1)*HR(I-1,I-1)+HI(I-1,I-1)*HI(I-1,I-1) &
&+SR*SR)
   XR = HR(I-1,I-1) / NORM
   WR(I-1) = XR
   XI = HI(I-1,I-1) / NORM
   WI(I-1) = XI
   HR(I-1,I-1) = NORM
   HI(I-1,I-1) = 0.0
   HI(I,I-1) = SR / NORM
!
   DO J = I, N
      YR = HR(I-1,J)
      YI = HI(I-1,J)
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      HR(I-1,J) = XR * YR + XI * YI + HI(I,I-1) * ZZR
      HI(I-1,J) = XR * YI - XI * YR + HI(I,I-1) * ZZI
      HR(I,J) = XR * ZZR - XI * ZZI - HI(I,I-1) * YR
      HI(I,J) = XR * ZZI + XI * ZZR - HI(I,I-1) * YI
   END DO
!
END DO
!
SI = HI(EN,EN)
IF (SI .EQ. 0.0) GO TO 540
NORM = CABS(CMPLX(HR(EN,EN),SI))
SR = HR(EN,EN) / NORM
SI = SI / NORM
HR(EN,EN) = NORM
HI(EN,EN) = 0.0
IF (EN .EQ. N) GO TO 540
IP1 = EN + 1
!
DO J = IP1, N
   YR = HR(EN,J)
   YI = HI(EN,J)
   HR(EN,J) = SR * YR + SI * YI
   HI(EN,J) = SR * YI - SI * YR
END DO
!     ********** INVERSE OPERATION (COLUMNS) **********
540 DO J = LP1, EN
   XR = WR(J-1)
   XI = WI(J-1)
!
   DO I = 1, J
      YR = HR(I,J-1)
      YI = 0.0
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      IF (I .EQ. J) GO TO 560
      YI = HI(I,J-1)
      HI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
560 HR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      HR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      HI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
   DO I = LOW, IGH
      YR = ZR(I,J-1)
      YI = ZI(I,J-1)
      ZZR = ZR(I,J)
      ZZI = ZI(I,J)
      ZR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      ZI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
      ZR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      ZI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
END DO
!
IF (SI .EQ. 0.0) GO TO 240
!
DO I = 1, EN
   YR = HR(I,EN)
   YI = HI(I,EN)
   HR(I,EN) = SR * YR - SI * YI
   HI(I,EN) = SR * YI + SI * YR
END DO
!
DO I = LOW, IGH
   YR = ZR(I,EN)
   YI = ZI(I,EN)
   ZR(I,EN) = SR * YR - SI * YI
   ZI(I,EN) = SR * YI + SI * YR
END DO
!
GO TO 240
!     ********** A ROOT FOUND **********
660 HR(EN,EN) = HR(EN,EN) + TR
WR(EN) = HR(EN,EN)
HI(EN,EN) = HI(EN,EN) + TI
WI(EN) = HI(EN,EN)
EN = ENM1
GO TO 220
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
680 NORM = 0.0
!
do 720 I = 1, N
!
   do 720 J = I, N
      NORM = NORM + ABS(HR(I,J)) + ABS(HI(I,J))
720 CONTINUE
!
IF (N .EQ. 1 .OR. NORM .EQ. 0.0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 2 DO -- **********
DO NN = 2, N
   EN = N + 2 - NN
   XR = WR(EN)
   XI = WI(EN)
   ENM1 = EN - 1
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   DO II = 1, ENM1
      I = EN - II
      ZZR = HR(I,EN)
      ZZI = HI(I,EN)
      IF (I .EQ. ENM1) GO TO 760
      IP1 = I + 1
!
      DO J = IP1, ENM1
         ZZR = ZZR + HR(I,J) * HR(J,EN) - HI(I,J) * HI(J,EN)
         ZZI = ZZI + HR(I,J) * HI(J,EN) + HI(I,J) * HR(J,EN)
      END DO
!
760 YR = XR - WR(I)
      YI = XI - WI(I)
      IF (YR .EQ. 0.0 .AND. YI .EQ. 0.0) YR = MACHEP * NORM
      Z3 = CMPLX(ZZR,ZZI) / CMPLX(YR,YI)
      HR(I,EN) = REAL(Z3)
      HI(I,EN) = AIMAG(Z3)
   END DO
!
END DO
!     ********** END BACKSUBSTITUTION **********
ENM1 = N - 1
!     ********** VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, ENM1
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
   IP1 = I + 1
!
   DO J = IP1, N
      ZR(I,J) = HR(I,J)
      ZI(I,J) = HI(I,J)
   END DO
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW+1 DO -- **********
do 880 JJ = LOW, ENM1
   J = N + LOW - JJ
   M = MIN0(J-1,IGH)
!
   do 880 I = LOW, IGH
      ZZR = ZR(I,J)
      ZZI = ZI(I,J)
!
      DO K = LOW, M
         ZZR = ZZR + ZR(I,K) * HR(K,J) - ZI(I,K) * HI(K,J)
         ZZI = ZZI + ZR(I,K) * HI(K,J) + ZI(I,K) * HR(K,J)
      END DO
!
      ZR(I,J) = ZZR
      ZI(I,J) = ZZI
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 30 ITERATIONS **********
1000 IERR = EN
1001 RETURN
!     ********** LAST CARD OF COMQR2 **********
END SUBROUTINE COMQR2

SUBROUTINE DCEIG(IBAL,AR,AI,KA,N,WR,WI,IERR)
!-----------------------------------------------------------------------
!            EIGENVALUES OF DOUBLE PRECISION COMPLEX MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION AR(KA,N), AI(KA,N), WR(N), WI(N)
!
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DCBAL(KA,N,AR,AI,LOW,IGH,WR)
CALL DCORTH(KA,N,LOW,IGH,AR,AI,WR,WI)
CALL DCOMQR(KA,N,LOW,IGH,AR,AI,WR,WI,IERR)
RETURN
END SUBROUTINE DCEIG

SUBROUTINE DCEIGV (IBAL,AR,AI,KA,N,WR,WI,ZR,ZI,IERR,TEMP)
!-----------------------------------------------------------------------
!                     EIGENVALUES AND EIGENVECTORS
!                 OF DOUBLE PRECISION COMPLEX MATRICES
!-----------------------------------------------------------------------
DOUBLE PRECISION AR(KA,N),AI(KA,N),WR(N),WI(N),ZR(KA,N),ZI(KA,N), &
&TEMP(*)
!----------------------
!     TEMP IS A TEMPORARY STORAGE AREA
!        DIMENSION(TEMP) .GE. 2*N    IF IBAL .EQ. 0
!        DIMENSION(TEMP) .GE. 3*N    IF IBAL .NE. 0
!----------------------
I2 = 1
I3 = N + 1
I1 = N + I3
LOW = 1
IGH = N
IF (IBAL .NE. 0) CALL DCBAL(KA,N,AR,AI,LOW,IGH,TEMP(I1))
CALL DCORTH(KA,N,LOW,IGH,AR,AI,TEMP(I2),TEMP(I3))
CALL DCMQR2(KA,N,LOW,IGH,TEMP(I2),TEMP(I3),AR,AI,WR,WI, &
&ZR,ZI,IERR)
IF (IERR .NE. 0) RETURN
IF (IBAL .NE. 0) CALL DCBABK(KA,N,LOW,IGH,TEMP(I1),N,ZR,ZI)
RETURN
END SUBROUTINE DCEIGV

SUBROUTINE DCBAL(NM,N,AR,AI,LOW,IGH,SCALE)
!
INTEGER I,J,K,L,M,N,JJ,NM,IGH,LOW,IEXC
DOUBLE PRECISION AR(NM,N),AI(NM,N),SCALE(N)
DOUBLE PRECISION C,F,G,R,S,B2,RADIX
LOGICAL NOCONV
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE
!     CBALANCE, WHICH IS A COMPLEX VERSION OF BALANCE,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     DCBAL BALANCES A DOUBLE PRECISION COMPLEX MATRIX AND
!     ISOLATES EIGENVALUES WHENEVER POSSIBLE.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX MATRIX TO BE BALANCED.
!
!     ON OUTPUT-
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE BALANCED MATRIX,
!
!        LOW AND IGH ARE TWO INTEGERS SUCH THAT AR(I,J) AND AI(I,J)
!          ARE EQUAL TO ZERO IF
!           (1) I IS GREATER THAN J AND
!           (2) J=1,...,LOW-1 OR I=IGH+1,...,N,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE
!           PERMUTATIONS AND SCALING FACTORS USED.
!
!     SUPPOSE THAT THE PRINCIPAL SUBMATRIX IN ROWS LOW THROUGH IGH
!     HAS BEEN BALANCED, THAT P(J) DENOTES THE INDEX INTERCHANGED
!     WITH J DURING THE PERMUTATION STEP, AND THAT THE ELEMENTS
!     OF THE DIAGONAL MATRIX USED ARE DENOTED BY D(I,J).  THEN
!        SCALE(J) = P(J),    FOR J = 1,...,LOW-1
!                 = D(J,J)       J = LOW,...,IGH
!                 = P(J)         J = IGH+1,...,N.
!     THE ORDER IN WHICH THE INTERCHANGES ARE MADE IS N TO IGH+1,
!     THEN 1 TO LOW-1.
!
!     NOTE THAT 1 IS RETURNED FOR IGH IF IGH IS ZERO FORMALLY.
!
!     THE ALGOL PROCEDURE EXC CONTAINED IN CBALANCE APPEARS IN
!     DCBAL IN LINE.  (NOTE THAT THE ALGOL ROLES OF IDENTIFIERS
!     K,L HAVE BEEN REVERSED.)
!
!-----------------------------------------------------------------------
!
!     ********** RADIX IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE BASE OF THE MACHINE FLOATING POINT REPRESENTATION.
!
           RADIX = IPMPAR(4)
!
!                **********
!
B2 = RADIX * RADIX
K = 1
L = N
GO TO 100
!     ********** IN-LINE PROCEDURE FOR ROW AND
!                COLUMN EXCHANGE **********
20 SCALE(M) = J
IF (J .EQ. M) GO TO 50
!
DO I = 1, L
   F = AR(I,J)
   AR(I,J) = AR(I,M)
   AR(I,M) = F
   F = AI(I,J)
   AI(I,J) = AI(I,M)
   AI(I,M) = F
END DO
!
DO I = K, N
   F = AR(J,I)
   AR(J,I) = AR(M,I)
   AR(M,I) = F
   F = AI(J,I)
   AI(J,I) = AI(M,I)
   AI(M,I) = F
END DO
!
50 GO TO (80,130), IEXC
!     ********** SEARCH FOR ROWS ISOLATING AN EIGENVALUE
!                AND PUSH THEM DOWN **********
80 IF (L .EQ. 1) GO TO 280
L = L - 1
!     ********** FOR J=L STEP -1 UNTIL 1 DO -- **********
100 do 120 JJ = 1, L
   J = L + 1 - JJ
!
   do 110 I = 1, L
      IF (I .EQ. J) GO TO 110
      IF (AR(J,I) .NE. 0.D0 .OR. AI(J,I) .NE. 0.D0) GO TO 120
110 CONTINUE
!
   M = L
   IEXC = 1
   GO TO 20
120 CONTINUE
!
GO TO 140
!     ********** SEARCH FOR COLUMNS ISOLATING AN EIGENVALUE
!                AND PUSH THEM LEFT **********
130 K = K + 1
!
140 do 170 J = K, L
!
   do 150 I = K, L
      IF (I .EQ. J) GO TO 150
      IF (AR(I,J) .NE. 0.D0 .OR. AI(I,J) .NE. 0.D0) GO TO 170
150 CONTINUE
!
   M = K
   IEXC = 2
   GO TO 20
170 CONTINUE
!     ********** NOW BALANCE THE SUBMATRIX IN ROWS K TO L **********
do 180 I = K, L
180 SCALE(I) = 1.D0
!     ********** ITERATIVE LOOP FOR NORM REDUCTION **********
190 NOCONV = .FALSE.
!
do 270 I = K, L
   C = 0.D0
   R = 0.D0
!
   do 200 J = K, L
      IF (J .EQ. I) GO TO 200
      C = C + DABS(AR(J,I)) + DABS(AI(J,I))
      R = R + DABS(AR(I,J)) + DABS(AI(I,J))
200 CONTINUE
!     ********** GUARD AGAINST ZERO C OR R DUE TO UNDERFLOW **********
   IF (C .EQ. 0.D0 .OR. R .EQ. 0.D0) GO TO 270
   G = R / RADIX
   F = 1.D0
   S = C + R
210 IF (C .GE. G) GO TO 220
   F = F * RADIX
   C = C * B2
   GO TO 210
220 G = R * RADIX
230 IF (C .LT. G) GO TO 240
   F = F / RADIX
   C = C / B2
   GO TO 230
!     ********** NOW BALANCE **********
240 IF ((C + R) / F .GE. 0.95D0 * S) GO TO 270
   G = 1.D0 / F
   SCALE(I) = SCALE(I) * F
   NOCONV = .TRUE.
!
   DO J = K, N
      AR(I,J) = AR(I,J) * G
      AI(I,J) = AI(I,J) * G
   END DO
!
   DO J = 1, L
      AR(J,I) = AR(J,I) * F
      AI(J,I) = AI(J,I) * F
   END DO
!
270 CONTINUE
!
IF (NOCONV) GO TO 190
!
280 LOW = K
IGH = L
RETURN
!     ********** LAST CARD OF DCBAL **********
END SUBROUTINE DCBAL

SUBROUTINE DCORTH(NM,N,LOW,IGH,AR,AI,ORTR,ORTI)
!
INTEGER I,J,M,N,II,JJ,LA,MP,NM,IGH,KP1,LOW
DOUBLE PRECISION AR(NM,N),AI(NM,N),ORTR(IGH),ORTI(IGH)
DOUBLE PRECISION F,G,H,FI,FR,SCALE
DOUBLE PRECISION DCPABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A COMPLEX ANALOGUE OF
!     THE ALGOL PROCEDURE ORTHES, NUM. MATH. 12, 349-368(1968)
!     BY MARTIN AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 339-358(1971).
!
!     GIVEN A DOUBLE PRECISION COMPLEX MATRIX, DCORTH
!     REDUCES A SUBMATRIX SITUATED IN ROWS AND COLUMNS
!     LOW THROUGH IGH TO UPPER HESSENBERG FORM BY
!     UNITARY SIMILARITY TRANSFORMATIONS.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DCBAL.  IF DCBAL HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX INPUT MATRIX.
!
!     ON OUTPUT-
!
!        AR AND AI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE HESSENBERG MATRIX.  INFORMATION
!          ABOUT THE UNITARY TRANSFORMATIONS USED IN THE REDUCTION
!          IS STORED IN THE REMAINING TRIANGLES UNDER THE
!          HESSENBERG MATRIX,
!
!        ORTR AND ORTI CONTAIN FURTHER INFORMATION ABOUT THE
!          TRANSFORMATIONS.  ONLY ELEMENTS LOW THROUGH IGH ARE USED.
!
!-----------------------------------------------------------------------
LA = IGH - 1
KP1 = LOW + 1
IF (LA .LT. KP1) GO TO 200
!
do 180 M = KP1, LA
   H = 0.D0
   ORTR(M) = 0.D0
   ORTI(M) = 0.D0
   SCALE = 0.D0
!     ********** SCALE COLUMN (ALGOL TOL THEN NOT NEEDED) **********
   do 90 I = M, IGH
90 SCALE = SCALE + DABS(AR(I,M-1)) + DABS(AI(I,M-1))
!
   IF (SCALE .EQ. 0.D0) GO TO 180
   MP = M + IGH
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
   DO II = M, IGH
      I = MP - II
      ORTR(I) = AR(I,M-1) / SCALE
      ORTI(I) = AI(I,M-1) / SCALE
      H = H + ORTR(I) * ORTR(I) + ORTI(I) * ORTI(I)
   END DO
!
   G = DSQRT(H)
   F = DCPABS(ORTR(M),ORTI(M))
   IF (F .EQ. 0.D0) GO TO 103
   H = H + F * G
   G = G / F
   ORTR(M) = (1.D0 + G) * ORTR(M)
   ORTI(M) = (1.D0 + G) * ORTI(M)
   GO TO 105
!
103 ORTR(M) = G
   AR(M,M-1) = SCALE
!     ********** FORM (I-(U*UT)/H) * A **********
105 DO J = M, N
      FR = 0.D0
      FI = 0.D0
!     ********** FOR I=IGH STEP -1 UNTIL M DO -- **********
      DO II = M, IGH
         I = MP - II
         FR = FR + ORTR(I) * AR(I,J) + ORTI(I) * AI(I,J)
         FI = FI + ORTR(I) * AI(I,J) - ORTI(I) * AR(I,J)
      END DO
!
      FR = FR / H
      FI = FI / H
!
      DO I = M, IGH
         AR(I,J) = AR(I,J) - FR * ORTR(I) + FI * ORTI(I)
         AI(I,J) = AI(I,J) - FR * ORTI(I) - FI * ORTR(I)
      END DO
!
   END DO
!     ********** FORM (I-(U*UT)/H)*A*(I-(U*UT)/H) **********
   DO I = 1, IGH
      FR = 0.D0
      FI = 0.D0
!     ********** FOR J=IGH STEP -1 UNTIL M DO -- **********
      DO JJ = M, IGH
         J = MP - JJ
         FR = FR + ORTR(J) * AR(I,J) - ORTI(J) * AI(I,J)
         FI = FI + ORTR(J) * AI(I,J) + ORTI(J) * AR(I,J)
      END DO
!
      FR = FR / H
      FI = FI / H
!
      DO J = M, IGH
         AR(I,J) = AR(I,J) - FR * ORTR(J) - FI * ORTI(J)
         AI(I,J) = AI(I,J) + FR * ORTI(J) - FI * ORTR(J)
      END DO
!
   END DO
!
   ORTR(M) = SCALE * ORTR(M)
   ORTI(M) = SCALE * ORTI(M)
   AR(M,M-1) = -G * AR(M,M-1)
   AI(M,M-1) = -G * AI(M,M-1)
180 CONTINUE
!
200 RETURN
!     ********** LAST CARD OF DCORTH **********
END SUBROUTINE DCORTH

SUBROUTINE DCOMQR(NM,N,LOW,IGH,HR,HI,WR,WI,IERR)
!
INTEGER I,J,L,N,EN,LL,NM,IGH,ITS,LOW,LP1,ENM1,IERR
DOUBLE PRECISION HR(NM,N),HI(NM,N),WR(N),WI(N)
DOUBLE PRECISION SI,SR,TI,TR,XI,XR,YI,YR,ZZI,ZZR,NORM,MACHEP
DOUBLE PRECISION R2,W(2),Z(2)
DOUBLE PRECISION DPMPAR,DCPABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A UNITARY ANALOGUE OF THE
!     ALGOL PROCEDURE  COMLR, NUM. MATH. 12, 369-376(1968) BY MARTIN
!     AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 396-403(1971).
!     THE UNITARY ANALOGUE SUBSTITUTES THE QR ALGORITHM OF FRANCIS
!     (COMP. JOUR. 4, 332-345(1962)) FOR THE LR ALGORITHM.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES OF A DOUBLE PRECISION
!     COMPLEX UPPER HESSENBERG MATRIX BY THE QR METHOD.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DCBAL.  IF DCBAL HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        HR AND HI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX UPPER HESSENBERG MATRIX.
!          THEIR LOWER TRIANGLES BELOW THE SUBDIAGONAL CONTAIN
!          INFORMATION ABOUT THE UNITARY TRANSFORMATIONS USED IN
!          THE REDUCTION BY DCORTH, IF PERFORMED.
!
!     ON OUTPUT-
!
!        THE UPPER HESSENBERG PORTIONS OF HR AND HI HAVE BEEN
!          DESTROYED.  THEREFORE, THEY MUST BE SAVED BEFORE
!          CALLING DCOMQR IF SUBSEQUENT CALCULATION OF
!          EIGENVECTORS IS TO BE PERFORMED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  IF AN ERROR
!          EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE RELATIVE PRECISION OF FLOATING POINT ARITHMETIC.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
IF (LOW .EQ. IGH) GO TO 180
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
L = LOW + 1
!
do 170 I = L, IGH
   LL = MIN0(I+1,IGH)
   IF (HI(I,I-1) .EQ. 0.D0) GO TO 170
   NORM = DCPABS(HR(I,I-1),HI(I,I-1))
   YR = HR(I,I-1) / NORM
   YI = HI(I,I-1) / NORM
   HR(I,I-1) = NORM
   HI(I,I-1) = 0.D0
!
   DO J = I, IGH
      SI = YR * HI(I,J) - YI * HR(I,J)
      HR(I,J) = YR * HR(I,J) + YI * HI(I,J)
      HI(I,J) = SI
   END DO
!
   DO J = LOW, LL
      SI = YR * HI(J,I) + YI * HR(J,I)
      HR(J,I) = YR * HR(J,I) - YI * HI(J,I)
      HI(J,I) = SI
   END DO
!
170 CONTINUE
!     ********** STORE ROOTS ISOLATED BY DCBAL **********
180 do 200 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 200
   WR(I) = HR(I,I)
   WI(I) = HI(I,I)
200 CONTINUE
!
EN = IGH
TR = 0.D0
TI = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 IF (EN .LT. LOW) GO TO 1001
ITS = 0
ENM1 = EN - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW  -- **********
240 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 300
   IF (DABS(HR(L,L-1)) .LE. &
&MACHEP * (DABS(HR(L-1,L-1)) + DABS(HI(L-1,L-1)) &
&+ DABS(HR(L,L)) + DABS(HI(L,L)))) GO TO 300
END DO
!     ********** FORM SHIFT **********
300 IF (L .EQ. EN) GO TO 660
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .EQ. 10 .OR. ITS .EQ. 20 .OR. ITS .EQ. 30) GO TO 320
SR = HR(EN,EN)
SI = HI(EN,EN)
XR = HR(ENM1,EN) * HR(EN,ENM1)
XI = HI(ENM1,EN) * HR(EN,ENM1)
IF (XR .EQ. 0.D0 .AND. XI .EQ. 0.D0) GO TO 340
YR = (HR(ENM1,ENM1) - SR) / 2.D0
YI = (HI(ENM1,ENM1) - SI) / 2.D0
Z(1) = YR*YR - YI*YI + XR
Z(2) = 2.D0*YR*YI + XI
CALL DCSQRT(Z,W)
ZZR = W(1)
ZZI = W(2)
IF (YR * ZZR + YI * ZZI .GE. 0.D0) GO TO 310
ZZR = -ZZR
ZZI = -ZZI
310 Z(1) = YR + ZZR
Z(2) = YI + ZZI
R2 = Z(1)**2 + Z(2)**2
SR = SR - (XR*Z(1) + XI*Z(2))/R2
SI = SI - (XI*Z(1) - XR*Z(2))/R2
GO TO 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 SR = DABS(HR(EN,ENM1)) + DABS(HR(ENM1,EN-2))
SI = 0.D0
!
340 DO I = LOW, EN
   HR(I,I) = HR(I,I) - SR
   HI(I,I) = HI(I,I) - SI
END DO
!
TR = TR + SR
TI = TI + SI
ITS = ITS + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
LP1 = L + 1
!
DO I = LP1, EN
   SR = HR(I,I-1)
   HR(I,I-1) = 0.D0
   NORM = DSQRT(HR(I-1,I-1)*HR(I-1,I-1)+HI(I-1,I-1)*HI(I-1,I-1) &
&+ SR*SR)
   XR = HR(I-1,I-1) / NORM
   WR(I-1) = XR
   XI = HI(I-1,I-1) / NORM
   WI(I-1) = XI
   HR(I-1,I-1) = NORM
   HI(I-1,I-1) = 0.D0
   HI(I,I-1) = SR / NORM
!
   DO J = I, EN
      YR = HR(I-1,J)
      YI = HI(I-1,J)
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      HR(I-1,J) = XR * YR + XI * YI + HI(I,I-1) * ZZR
      HI(I-1,J) = XR * YI - XI * YR + HI(I,I-1) * ZZI
      HR(I,J) = XR * ZZR - XI * ZZI - HI(I,I-1) * YR
      HI(I,J) = XR * ZZI + XI * ZZR - HI(I,I-1) * YI
   END DO
!
END DO
!
SI = HI(EN,EN)
IF (SI .EQ. 0.D0) GO TO 540
NORM = DCPABS(HR(EN,EN),SI)
SR = HR(EN,EN) / NORM
SI = SI / NORM
HR(EN,EN) = NORM
HI(EN,EN) = 0.D0
!     ********** INVERSE OPERATION (COLUMNS) **********
540 DO J = LP1, EN
   XR = WR(J-1)
   XI = WI(J-1)
!
   DO I = L, J
      YR = HR(I,J-1)
      YI = 0.D0
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      IF (I .EQ. J) GO TO 560
      YI = HI(I,J-1)
      HI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
560 HR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      HR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      HI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
END DO
!
IF (SI .EQ. 0.D0) GO TO 240
!
DO I = L, EN
   YR = HR(I,EN)
   YI = HI(I,EN)
   HR(I,EN) = SR * YR - SI * YI
   HI(I,EN) = SR * YI + SI * YR
END DO
!
GO TO 240
!     ********** A ROOT FOUND **********
660 WR(EN) = HR(EN,EN) + TR
WI(EN) = HI(EN,EN) + TI
EN = ENM1
GO TO 220
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
END SUBROUTINE DCOMQR

SUBROUTINE DCBABK (NM,N,LOW,IGH,SCALE,M,ZR,ZI)
!
INTEGER I,J,K,M,N,II,NM,IGH,LOW
DOUBLE PRECISION SCALE(N),ZR(NM,M),ZI(NM,M)
DOUBLE PRECISION S
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF THE ALGOL PROCEDURE
!     CBABK2, WHICH IS A COMPLEX VERSION OF BALBAK,
!     NUM. MATH. 13, 293-304(1969) BY PARLETT AND REINSCH.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 315-326(1971).
!
!     THIS SUBROUTINE FORMS THE EIGENVECTORS OF A DOUBLE PRECISION
!     COMPLEX MATRIX BY BACK TRANSFORMING THOSE OF THE CORRESPONDING
!     BALANCED MATRIX DETERMINED BY DCBAL.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY DCBAL,
!
!        SCALE CONTAINS INFORMATION DETERMINING THE PERMUTATIONS
!          AND SCALING FACTORS USED BY DCBAL,
!
!        M IS THE NUMBER OF EIGENVECTORS TO BE BACK TRANSFORMED,
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVECTORS TO BE
!          BACK TRANSFORMED IN THEIR FIRST M COLUMNS.
!
!     ON OUTPUT-
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE TRANSFORMED EIGENVECTORS
!          IN THEIR FIRST M COLUMNS.
!
!-----------------------------------------------------------------------
IF (M .EQ. 0) GO TO 200
IF (IGH .EQ. LOW) GO TO 120
!
DO I = LOW, IGH
   S = SCALE(I)
!     ********** LEFT HAND EIGENVECTORS ARE BACK TRANSFORMED
!                IF THE FOREGOING STATEMENT IS REPLACED BY
!                S=1.0/SCALE(I). **********
   DO J = 1, M
      ZR(I,J) = ZR(I,J) * S
      ZI(I,J) = ZI(I,J) * S
   END DO
!
END DO
!
!     ********** FOR I=LOW-1 STEP -1 UNTIL 1,
!                IGH+1 STEP 1 UNTIL N DO -- **********
120 do 140 II = 1, N
   I = II
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 140
   IF (I .LT. LOW) I = LOW - II
   K = SCALE(I)
   IF (K .EQ. I) GO TO 140
!
   DO J = 1, M
      S = ZR(I,J)
      ZR(I,J) = ZR(K,J)
      ZR(K,J) = S
      S = ZI(I,J)
      ZI(I,J) = ZI(K,J)
      ZI(K,J) = S
   END DO
!
140 CONTINUE
!
200 RETURN
!     ********** LAST CARD OF DCBABK **********
END SUBROUTINE DCBABK

SUBROUTINE DCMQR2 (NM,N,LOW,IGH,ORTR,ORTI,HR,HI,WR,WI,ZR,ZI,IERR)
!
INTEGER I,J,K,L,M,N,EN,II,JJ,LL,NM,NN,IGH,IP1, &
&ITS,LOW,LP1,ENM1,IEND,IERR
DOUBLE PRECISION HR(NM,N),HI(NM,N),WR(N),WI(N),ZR(NM,N),ZI(NM,N), &
&ORTR(IGH),ORTI(IGH)
DOUBLE PRECISION SI,SR,TI,TR,XI,XR,YI,YR,ZZI,ZZR,NORM,MACHEP
DOUBLE PRECISION R2,W(2),Z(2)
DOUBLE PRECISION DPMPAR,DCPABS
!-----------------------------------------------------------------------
!
!     THIS SUBROUTINE IS A TRANSLATION OF A UNITARY ANALOGUE OF THE
!     ALGOL PROCEDURE  COMLR2, NUM. MATH. 16, 181-204(1970) BY PETERS
!     AND WILKINSON.
!     HANDBOOK FOR AUTO. COMP., VOL.II-LINEAR ALGEBRA, 372-395(1971).
!     THE UNITARY ANALOGUE SUBSTITUTES THE QR ALGORITHM OF FRANCIS
!     (COMP. JOUR. 4, 332-345(1962)) FOR THE LR ALGORITHM.
!
!     THIS SUBROUTINE FINDS THE EIGENVALUES AND EIGENVECTORS OF
!     A DOUBLE PRECISION COMPLEX UPPER HESSENBERG MATRIX BY THE
!     QR METHOD.  THE EIGENVECTORS OF A COMPLEX GENERAL MATRIX
!     CAN ALSO BE FOUND IF DCORTH HAS BEEN USED TO REDUCE
!     THIS GENERAL MATRIX TO HESSENBERG FORM.
!
!     ON INPUT-
!
!        NM MUST BE SET TO THE ROW DIMENSION OF TWO-DIMENSIONAL
!          ARRAY PARAMETERS AS DECLARED IN THE CALLING PROGRAM
!          DIMENSION STATEMENT,
!
!        N IS THE ORDER OF THE MATRIX,
!
!        LOW AND IGH ARE INTEGERS DETERMINED BY THE BALANCING
!          SUBROUTINE DCBAL.  IF DCBAL HAS NOT BEEN USED,
!          SET LOW=1, IGH=N,
!
!        ORTR AND ORTI CONTAIN INFORMATION ABOUT THE UNITARY TRANS-
!          FORMATIONS USED IN THE REDUCTION BY DCORTH, IF PERFORMED.
!          ONLY ELEMENTS LOW THROUGH IGH ARE USED.  IF THE EIGENVECTORS
!          OF THE HESSENBERG MATRIX ARE DESIRED, SET ORTR(J) AND
!          ORTI(J) TO 0.0 FOR THESE ELEMENTS,
!
!        HR AND HI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE COMPLEX UPPER HESSENBERG MATRIX.
!          THEIR LOWER TRIANGLES BELOW THE SUBDIAGONAL CONTAIN FURTHER
!          INFORMATION ABOUT THE TRANSFORMATIONS WHICH WERE USED IN THE
!          REDUCTION BY DCORTH, IF PERFORMED.  IF THE EIGENVECTORS OF
!          THE HESSENBERG MATRIX ARE DESIRED, THESE ELEMENTS MAY BE
!          ARBITRARY.
!
!     ON OUTPUT-
!
!        ORTR, ORTI, AND THE UPPER HESSENBERG PORTIONS OF HR AND HI
!          HAVE BEEN DESTROYED,
!
!        WR AND WI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVALUES.  IF AN ERROR
!          EXIT IS MADE, THE EIGENVALUES SHOULD BE CORRECT
!          FOR INDICES IERR+1,...,N,
!
!        ZR AND ZI CONTAIN THE REAL AND IMAGINARY PARTS,
!          RESPECTIVELY, OF THE EIGENVECTORS.  THE EIGENVECTORS
!          ARE UNNORMALIZED.  IF AN ERROR EXIT IS MADE, NONE OF
!          THE EIGENVECTORS HAS BEEN FOUND,
!
!        IERR IS SET TO
!          ZERO       FOR NORMAL RETURN,
!          J          IF THE J-TH EIGENVALUE HAS NOT BEEN
!                     DETERMINED AFTER 50 ITERATIONS.
!
!-----------------------------------------------------------------------
!
!     ********** MACHEP IS A MACHINE DEPENDENT PARAMETER SPECIFYING
!                THE RELATIVE PRECISION OF FLOATING POINT ARITHMETIC.
!
           MACHEP = DPMPAR(1)
!
!                **********
!
IERR = 0
!     ********** INITIALIZE EIGENVECTOR MATRIX **********
do 100 I = 1, N
!
   do 100 J = 1, N
      ZR(I,J) = 0.D0
      ZI(I,J) = 0.D0
      IF (I .EQ. J) ZR(I,J) = 1.D0
100 CONTINUE
!     ********** FORM THE MATRIX OF ACCUMULATED TRANSFORMATIONS
!                FROM THE INFORMATION LEFT BY DCORTH **********
IEND = IGH - LOW - 1
IF (IEND) 180, 150, 105
!     ********** FOR I=IGH-1 STEP -1 UNTIL LOW+1 DO -- **********
105 do 140 II = 1, IEND
   I = IGH - II
   IF (ORTR(I) .EQ. 0.D0 .AND. ORTI(I) .EQ. 0.D0) GO TO 140
   IF (HR(I,I-1) .EQ. 0.D0 .AND. HI(I,I-1) .EQ. 0.D0) GO TO 140
!     ********** NORM BELOW IS NEGATIVE OF H FORMED IN DCORTH **********
   NORM = HR(I,I-1) * ORTR(I) + HI(I,I-1) * ORTI(I)
   IP1 = I + 1
!
   DO K = IP1, IGH
      ORTR(K) = HR(K,I-1)
      ORTI(K) = HI(K,I-1)
   END DO
!
   DO J = I, IGH
      SR = 0.D0
      SI = 0.D0
!
      DO K = I, IGH
         SR = SR + ORTR(K) * ZR(K,J) + ORTI(K) * ZI(K,J)
         SI = SI + ORTR(K) * ZI(K,J) - ORTI(K) * ZR(K,J)
      END DO
!
      SR = SR / NORM
      SI = SI / NORM
!
      DO K = I, IGH
         ZR(K,J) = ZR(K,J) + SR * ORTR(K) - SI * ORTI(K)
         ZI(K,J) = ZI(K,J) + SR * ORTI(K) + SI * ORTR(K)
      END DO
!
   END DO
!
140 CONTINUE
!     ********** CREATE REAL SUBDIAGONAL ELEMENTS **********
150 L = LOW + 1
!
do 170 I = L, IGH
   LL = MIN0(I+1,IGH)
   IF (HI(I,I-1) .EQ. 0.D0) GO TO 170
   NORM = DCPABS(HR(I,I-1),HI(I,I-1))
   YR = HR(I,I-1) / NORM
   YI = HI(I,I-1) / NORM
   HR(I,I-1) = NORM
   HI(I,I-1) = 0.D0
!
   DO J = I, N
      SI = YR * HI(I,J) - YI * HR(I,J)
      HR(I,J) = YR * HR(I,J) + YI * HI(I,J)
      HI(I,J) = SI
   END DO
!
   DO J = 1, LL
      SI = YR * HI(J,I) + YI * HR(J,I)
      HR(J,I) = YR * HR(J,I) - YI * HI(J,I)
      HI(J,I) = SI
   END DO
!
   DO J = LOW, IGH
      SI = YR * ZI(J,I) + YI * ZR(J,I)
      ZR(J,I) = YR * ZR(J,I) - YI * ZI(J,I)
      ZI(J,I) = SI
   END DO
!
170 CONTINUE
!     ********** STORE ROOTS ISOLATED BY DCBAL **********
180 do 200 I = 1, N
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 200
   WR(I) = HR(I,I)
   WI(I) = HI(I,I)
200 CONTINUE
!
EN = IGH
TR = 0.D0
TI = 0.D0
!     ********** SEARCH FOR NEXT EIGENVALUE **********
220 IF (EN .LT. LOW) GO TO 680
ITS = 0
ENM1 = EN - 1
!     ********** LOOK FOR SINGLE SMALL SUB-DIAGONAL ELEMENT
!                FOR L=EN STEP -1 UNTIL LOW DO -- **********
240 DO LL = LOW, EN
   L = EN + LOW - LL
   IF (L .EQ. LOW) GO TO 300
   IF (DABS(HR(L,L-1)) .LE. &
&MACHEP * (DABS(HR(L-1,L-1)) + DABS(HI(L-1,L-1)) &
&+ DABS(HR(L,L)) + DABS(HI(L,L)))) GO TO 300
END DO
!     ********** FORM SHIFT **********
300 IF (L .EQ. EN) GO TO 660
IF (ITS .EQ. 50) GO TO 1000
IF (ITS .EQ. 10 .OR. ITS .EQ. 20 .OR. ITS .EQ. 30) GO TO 320
SR = HR(EN,EN)
SI = HI(EN,EN)
XR = HR(ENM1,EN) * HR(EN,ENM1)
XI = HI(ENM1,EN) * HR(EN,ENM1)
IF (XR .EQ. 0.D0 .AND. XI .EQ. 0.D0) GO TO 340
YR = (HR(ENM1,ENM1) - SR) / 2.D0
YI = (HI(ENM1,ENM1) - SI) / 2.D0
Z(1) = YR*YR - YI*YI + XR
Z(2) = 2.D0*YR*YI + XI
CALL DCSQRT(Z,W)
ZZR = W(1)
ZZI = W(2)
IF (YR * ZZR + YI * ZZI .GE. 0.D0) GO TO 310
ZZR = -ZZR
ZZI = -ZZI
310 Z(1) = YR + ZZR
Z(2) = YI + ZZI
R2 = Z(1)**2 + Z(2)**2
SR = SR - (XR*Z(1) + XI*Z(2))/R2
SI = SI - (XI*Z(1) - XR*Z(2))/R2
GO TO 340
!     ********** FORM EXCEPTIONAL SHIFT **********
320 SR = DABS(HR(EN,ENM1)) + DABS(HR(ENM1,EN-2))
SI = 0.D0
!
340 DO I = LOW, EN
   HR(I,I) = HR(I,I) - SR
   HI(I,I) = HI(I,I) - SI
END DO
!
TR = TR + SR
TI = TI + SI
ITS = ITS + 1
!     ********** REDUCE TO TRIANGLE (ROWS) **********
LP1 = L + 1
!
DO I = LP1, EN
   SR = HR(I,I-1)
   HR(I,I-1) = 0.D0
   NORM = DSQRT(HR(I-1,I-1)*HR(I-1,I-1)+HI(I-1,I-1)*HI(I-1,I-1) &
&+ SR*SR)
   XR = HR(I-1,I-1) / NORM
   WR(I-1) = XR
   XI = HI(I-1,I-1) / NORM
   WI(I-1) = XI
   HR(I-1,I-1) = NORM
   HI(I-1,I-1) = 0.D0
   HI(I,I-1) = SR / NORM
!
   DO J = I, N
      YR = HR(I-1,J)
      YI = HI(I-1,J)
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      HR(I-1,J) = XR * YR + XI * YI + HI(I,I-1) * ZZR
      HI(I-1,J) = XR * YI - XI * YR + HI(I,I-1) * ZZI
      HR(I,J) = XR * ZZR - XI * ZZI - HI(I,I-1) * YR
      HI(I,J) = XR * ZZI + XI * ZZR - HI(I,I-1) * YI
   END DO
!
END DO
!
SI = HI(EN,EN)
IF (SI .EQ. 0.D0) GO TO 540
NORM = DCPABS(HR(EN,EN),SI)
SR = HR(EN,EN) / NORM
SI = SI / NORM
HR(EN,EN) = NORM
HI(EN,EN) = 0.D0
IF (EN .EQ. N) GO TO 540
IP1 = EN + 1
!
DO J = IP1, N
   YR = HR(EN,J)
   YI = HI(EN,J)
   HR(EN,J) = SR * YR + SI * YI
   HI(EN,J) = SR * YI - SI * YR
END DO
!     ********** INVERSE OPERATION (COLUMNS) **********
540 DO J = LP1, EN
   XR = WR(J-1)
   XI = WI(J-1)
!
   DO I = 1, J
      YR = HR(I,J-1)
      YI = 0.D0
      ZZR = HR(I,J)
      ZZI = HI(I,J)
      IF (I .EQ. J) GO TO 560
      YI = HI(I,J-1)
      HI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
560 HR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      HR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      HI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
   DO I = LOW, IGH
      YR = ZR(I,J-1)
      YI = ZI(I,J-1)
      ZZR = ZR(I,J)
      ZZI = ZI(I,J)
      ZR(I,J-1) = XR * YR - XI * YI + HI(J,J-1) * ZZR
      ZI(I,J-1) = XR * YI + XI * YR + HI(J,J-1) * ZZI
      ZR(I,J) = XR * ZZR + XI * ZZI - HI(J,J-1) * YR
      ZI(I,J) = XR * ZZI - XI * ZZR - HI(J,J-1) * YI
   END DO
!
END DO
!
IF (SI .EQ. 0.D0) GO TO 240
!
DO I = 1, EN
   YR = HR(I,EN)
   YI = HI(I,EN)
   HR(I,EN) = SR * YR - SI * YI
   HI(I,EN) = SR * YI + SI * YR
END DO
!
DO I = LOW, IGH
   YR = ZR(I,EN)
   YI = ZI(I,EN)
   ZR(I,EN) = SR * YR - SI * YI
   ZI(I,EN) = SR * YI + SI * YR
END DO
!
GO TO 240
!     ********** A ROOT FOUND **********
660 HR(EN,EN) = HR(EN,EN) + TR
WR(EN) = HR(EN,EN)
HI(EN,EN) = HI(EN,EN) + TI
WI(EN) = HI(EN,EN)
EN = ENM1
GO TO 220
!     ********** ALL ROOTS FOUND.  BACKSUBSTITUTE TO FIND
!                VECTORS OF UPPER TRIANGULAR FORM **********
680 NORM = 0.D0
!
do 720 I = 1, N
!
   do 720 J = I, N
      NORM = NORM + DABS(HR(I,J)) + DABS(HI(I,J))
720 CONTINUE
!
IF (N .EQ. 1 .OR. NORM .EQ. 0.D0) GO TO 1001
!     ********** FOR EN=N STEP -1 UNTIL 2 DO -- **********
DO NN = 2, N
   EN = N + 2 - NN
   XR = WR(EN)
   XI = WI(EN)
   ENM1 = EN - 1
!     ********** FOR I=EN-1 STEP -1 UNTIL 1 DO -- **********
   DO II = 1, ENM1
      I = EN - II
      ZZR = HR(I,EN)
      ZZI = HI(I,EN)
      IF (I .EQ. ENM1) GO TO 760
      IP1 = I + 1
!
      DO J = IP1, ENM1
         ZZR = ZZR + HR(I,J) * HR(J,EN) - HI(I,J) * HI(J,EN)
         ZZI = ZZI + HR(I,J) * HI(J,EN) + HI(I,J) * HR(J,EN)
      END DO
!
760 YR = XR - WR(I)
      YI = XI - WI(I)
      IF (YR .EQ. 0.D0 .AND. YI .EQ. 0.D0) YR = MACHEP * NORM
      R2 = YR*YR + YI*YI
      HR(I,EN) = (ZZR*YR + ZZI*YI)/R2
      HI(I,EN) = (ZZI*YR - ZZR*YI)/R2
   END DO
!
END DO
!     ********** END BACKSUBSTITUTION **********
ENM1 = N - 1
!     ********** VECTORS OF ISOLATED ROOTS **********
do 840 I = 1, ENM1
   IF (I .GE. LOW .AND. I .LE. IGH) GO TO 840
   IP1 = I + 1
!
   DO J = IP1, N
      ZR(I,J) = HR(I,J)
      ZI(I,J) = HI(I,J)
   END DO
!
840 CONTINUE
!     ********** MULTIPLY BY TRANSFORMATION MATRIX TO GIVE
!                VECTORS OF ORIGINAL FULL MATRIX.
!                FOR J=N STEP -1 UNTIL LOW+1 DO -- **********
do 880 JJ = LOW, ENM1
   J = N + LOW - JJ
   M = MIN0(J-1,IGH)
!
   do 880 I = LOW, IGH
      ZZR = ZR(I,J)
      ZZI = ZI(I,J)
!
      DO K = LOW, M
         ZZR = ZZR + ZR(I,K) * HR(K,J) - ZI(I,K) * HI(K,J)
         ZZI = ZZI + ZR(I,K) * HI(K,J) + ZI(I,K) * HR(K,J)
      END DO
!
      ZR(I,J) = ZZR
      ZI(I,J) = ZZI
880 CONTINUE
!
GO TO 1001
!     ********** SET ERROR -- NO CONVERGENCE TO AN
!                EIGENVALUE AFTER 50 ITERATIONS **********
1000 IERR = EN
1001 RETURN
!     ********** LAST CARD OF DCMQR2 **********
END SUBROUTINE DCMQR2

